window.TADABBUR_SHURA = {"_meta":{"description":"تدبّر سورة الشورى (٤٢)، وسورةٌ مكّيّةٌ من الحواميم. تُسمّى الشورى وحم عسق. محورُها وحدةُ الوحيِ الذي أوحاه الله إلى الأنبياء، وعظمةُ الله في السماواتِ والأرض، والدعوةُ إلى دينِ الله وعدمِ التفرّق، وأنّ الجزاءَ من جنسِ العمل، وصفاتُ المؤمنين ومنها أنّ أمرهم شورى بينهم. فيها «شرع لكم من الدين ما وصى به نوحا»، و«فاطر السماوات والأرض جعل لكم من أنفسكم أزواجا»، و«ما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير»، و«وأمرهم شورى بينهم»، و«وما كان لبشر أن يكلمه الله إلا وحيا».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":42,"name":"الشورى","total_ayahs":53,"audio":[1,11,13,19,23,30,38,40,51,52],"passages":[{"title":"وحدةُ الوحيِ وعظمةُ الله، واستغفارُ الملائكة، وأنّ الله هو الوليّ","range":[1,9],"theme":"افتتاحُ السورةِ بـ«حم عسق»، وأنّ الله العزيزَ الحكيمَ يوحي إلى النبيِّ كما أوحى إلى من قبله، وعظمتُه وعلوّه وأنّ له ما في السماواتِ والأرض، وتسبيحُ الملائكةِ واستغفارُهم لمن في الأرض، وأنه حفيظٌ على المشركين، وإيحاءُ القرآنِ لإنذارِ أمِّ القرى ويومِ الجمعِ حيث فريقٌ في الجنّةِ وفريقٌ في السعير، وأنّ الله هو الوليُّ الحقُّ المحيي للموتى القادرُ على كلِّ شيء","verses":[{"n":1,"reflection":{"text":"«حم»: حروفٌ مقطّعةٌ افتُتِحت بها السورةُ، من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه، ويُشار بها إلى إعجازِ القرآن؛ ففي هذا تنبيهٌ على عظمةِ القرآن؛ فسلّم لما استأثر الله بعلمه، وتدبّر ما بيّنه، فالتسليمُ فيما لم تعلم من صفاتِ الراسخين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ الشورى افتُتِحت بـ«حم» من الحروفِ المقطّعةِ التي افتُتِحت بها الحواميم، وهي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه «حم»؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآنِ المؤلَّفِ من جنسِ هذه الحروفِ التي تعرفونها؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك؛ فبالتسليمِ والعملِ تُنال الهداية."}},{"n":2,"reflection":{"text":"«عسق»: حروفٌ مقطّعةٌ أخرى، من المتشابهِ الذي استأثر الله بعلمه؛ ففي هذا تعظيمُ القرآنِ وتنبيهٌ على إعجازه؛ فسلّم لله فيما استأثر بعلمه، ولا تتكلّف الخوضَ فيما لا سبيلَ إلى علمه، بل اشتغل بما ينفعك من محكمِ القرآنِ والعملِ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والاشتغالُ بالمحكمِ النافع."},"action":{"text":"اعلم أنّ «عسق» من الحروفِ المقطّعةِ التي هي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه «عسق»؛ فهي مع «حم» فاتحةُ هذه السورة؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآن؛ فسلّم لله فيما استأثر بعلمه من المتشابه؛ ولا تتكلّف الخوضَ فيما لا سبيلَ لك إلى علمه على وجهِ اليقين؛ بل اشتغل بما ينفعك من محكمِ القرآنِ وتدبّره والعملِ به؛ فالمؤمنُ يؤمن بالكتابِ كلِّه، محكمِه ومتشابهِه؛ ويعمل بالمحكم، ويكل علمَ المتشابهِ إلى الله؛ فبهذا التسليمِ والعملِ تُنال السعادةُ والهداية؛ فلا تصرف وقتك فيما لا ينفعك من التنقيرِ عن أسرارِ الحروف؛ بل اجعل همّك تدبّرَ القرآنِ والعملَ به."}},{"n":3,"reflection":{"text":"«كذلك يوحي إليك وإلى الذين من قبلك الله العزيز الحكيم»: كما أوحى إلى الأنبياءِ قبلك يوحي إليك اللهُ العزيزُ الحكيم؛ ففي هذا وحدةُ مصدرِ الوحيِ وتقريرُ نبوّةِ محمدٍ في سلكِ الأنبياء؛ فآمن بأنّ الوحيَ واحدٌ من الله إلى جميعِ الأنبياء، فما جاء به محمدٌ هو ما جاء به من قبله من العزيزِ الحكيم، فاتّبع الوحيَ الواحد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بوحدةِ الوحيِ من الله إلى جميعِ الأنبياء."},"action":{"text":"تأمّل تقريرَ وحدةِ الوحي: كما أوحى الله إلى الأنبياءِ من قبلك يا محمد، يوحي إليك هذا القرآنَ اللهُ العزيزُ الغالبُ، الحكيمُ في خلقه وأمره وشرعه «كذلك يوحي إليك وإلى الذين من قبلك الله العزيز الحكيم»؛ ففي هذا بيانُ وحدةِ مصدرِ الوحي، وتقريرُ نبوّةِ محمدٍ ﷺ وأنه في سلكِ الأنبياءِ قبله؛ فالوحيُ الذي جاء به هو من جنسِ ما جاء به الأنبياء، من عند الله الواحد؛ فآمن بأنّ الوحيَ واحدٌ في مصدره وأصله، أوحاه الله إلى جميعِ الأنبياء؛ فما جاء به محمدٌ ﷺ من التوحيدِ وأصولِ الدينِ هو ما جاء به الأنبياءُ من قبله؛ لا نفرّق بين أحدٍ من رسله؛ فآمن بالرسلِ جميعًا وبما جاؤوا به من الوحي؛ واتّبع الوحيَ الواحدَ الذي أنزله العزيزُ الحكيم؛ فمن آمن بوحدةِ الوحيِ آمن بالرسلِ جميعًا واتّبع الحق؛ فاجعل إيمانك بالوحيِ راسخًا؛ فهو من العزيزِ الحكيم."}},{"n":4,"reflection":{"text":"«له ما في السماوات وما في الأرض وهو العلي العظيم»: له ملكُ ما في السماواتِ والأرض، وهو العليُّ فوق خلقه، العظيمُ في ذاته وصفاته؛ ففي هذا تقريرُ ملكِ الله وعلوّه وعظمته؛ فعظّم الله العليَّ العظيمَ في قلبك، فمن له كلُّ شيءٍ وهو العليُّ العظيمُ يستحقّ العبادةَ والتعظيم، فأخلص له العبادةَ وعظّمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله العليِّ العظيمِ مالكِ كلِّ شيء، وإخلاصُ العبادةِ له."},"action":{"text":"تأمّل عظمةَ الله وعلوّه: له وحده ملكُ ما في السماواتِ وما في الأرضِ خلقًا وملكًا وتدبيرًا؛ وهو العليُّ بذاته فوق خلقه المستوي على عرشه، العليُّ بقدره وقهره، العظيمُ في ذاته وأسمائه وصفاته الذي كلُّ شيءٍ دونه «له ما في السماوات وما في الأرض وهو العلي العظيم»؛ ففي هذا تقريرُ ملكِ الله الشاملِ وعلوّه وعظمته؛ فكلُّ ما في السماواتِ والأرضِ ملكٌ لله، عبيدٌ له، فقراءُ إليه؛ وهو العليُّ العظيمُ الذي لا أعلى منه ولا أعظم؛ فعظّم الله العليَّ العظيمَ في قلبك؛ واستشعر علوّه وعظمته وكبرياءه؛ فمن له كلُّ شيءٍ، وهو العليُّ العظيمُ، يستحقّ العبادةَ والتعظيمَ والإجلال؛ فأخلص له العبادةَ وحده؛ وعظّمه حقَّ تعظيمه؛ فمن عرف عظمةَ الله وعلوّه أخلص له العبادةَ وخضع له؛ فاجعل قلبك ممتلئًا بتعظيمِ الله وإجلاله؛ فبتعظيمِ الله يُخلَص التوحيد، وتُحسَن العبادة."}},{"n":5,"reflection":{"text":"«تكاد السماوات يتفطرن من فوقهن والملائكة يسبحون بحمد ربهم ويستغفرون لمن في الأرض ألا إن الله هو الغفور الرحيم»: تكاد السماواتُ يتشقّقن من عظمةِ الله (أو من قولِ المشركين الولد)، والملائكةُ يسبّحون بحمدِ ربّهم ويستغفرون لمن في الأرض، ألا إنّ الله هو الغفورُ الرحيم؛ ففي هذا عظمةُ الله واستغفارُ الملائكةِ للمؤمنين؛ فأبشر باستغفارِ الملائكةِ لك، وعظّم الله، وارجُ مغفرته، فالله الغفورُ الرحيمُ، فاطلب مغفرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في مغفرةِ الله، والفرحُ باستغفارِ الملائكةِ للمؤمنين."},"action":{"text":"تأمّل عظمةَ الله ورحمته: تكاد السماواتُ على عظمها يتشقّقن ويتفطّرن من فوقهنّ من عظمةِ الله وجلاله، أو من هولِ قولِ المشركين إنّ لله ولدًا؛ والملائكةُ يسبّحون بحمدِ ربّهم معظّمين منزّهين، ويستغفرون لمن في الأرضِ من المؤمنين؛ ألا إنّ الله هو الغفورُ لذنوبِ عباده، الرحيمُ بهم «تكاد السماوات يتفطرن من فوقهن والملائكة يسبحون بحمد ربهم ويستغفرون لمن في الأرض ألا إن الله هو الغفور الرحيم»؛ ففي هذا بيانُ عظمةِ الله، واستغفارِ الملائكةِ للمؤمنين، وسعةِ مغفرةِ الله ورحمته؛ فما أعظمَ كرامةَ المؤمنِ أن تستغفر له الملائكة! فأبشر أيها المؤمنُ باستغفارِ الملائكةِ لك؛ وعظّم الله الذي تكاد السماواتُ تتفطّر من عظمته؛ وارجُ مغفرته ورحمته؛ فهو الغفورُ الرحيم؛ فأكثر من الاستغفارِ والتوبةِ رجاءَ مغفرته؛ واعمل صالحًا رجاءَ رحمته؛ فمن رجا مغفرةَ الله ورحمته وعمل لهما نالهما؛ فاجمع بين تعظيمِ الله ورجاءِ مغفرته؛ فالله الغفورُ الرحيمُ، واسعُ المغفرةِ والرحمة؛ فاطلبهما بالتوبةِ والاستغفارِ والعمل."}},{"n":6,"reflection":{"text":"«والذين اتخذوا من دونه أولياء الله حفيظ عليهم وما أنت عليهم بوكيل»، والذين اتّخذوا من دونِ الله أولياءَ يعبدونهم، اللهُ رقيبٌ حفيظٌ على أعمالهم يجازيهم، ولست عليهم بموكّلٍ بهدايتهم؛ ففي هذا وعيدُ المشركين وتخفيفُ عبءِ الهدايةِ عن النبيّ؛ فاعلم أنّ الله حفيظٌ على أعمالِ الناس، فراقبه في عملك، وابذل الدعوةَ ولا تحزن على من لم يهتدِ، فليس عليك هداهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله الحفيظ، وبذلُ الدعوةِ دون حزنٍ على المعرض."},"action":{"text":"تأمّل وعيدَ المشركين وتسليةَ النبيّ: والذين اتّخذوا من دونِ الله أولياءَ من الأصنامِ والأندادِ يتولّونهم ويعبدونهم، اللهُ حفيظٌ رقيبٌ على أعمالهم، يحصيها عليهم ويجازيهم بها؛ ولست يا محمدُ عليهم بوكيلٍ موكّلٍ بحفظهم وهدايتهم، إنما عليك البلاغ «والذين اتخذوا من دونه أولياء الله حفيظ عليهم وما أنت عليهم بوكيل»؛ ففي هذا وعيدُ المشركين المتّخذين الأولياءَ من دونِ الله، وتخفيفُ عبءِ الهدايةِ عن النبيّ؛ فاعلم أنّ الله حفيظٌ رقيبٌ على أعمالِ الناسِ كلِّهم، يحصيها ويجازي عليها؛ فراقب الله الحفيظَ في عملك؛ فهو مطّلعٌ عليك، محصٍ لعملك؛ واعلم أنّ الهدايةَ بيدِ الله، وأنّ عليك البلاغَ لا الهداية؛ فابذل الدعوةَ والنصحَ لمن حولك؛ ثم لا تحزن على من لم يهتدِ بعد بلوغِ الحجّة؛ فلست عليهم بوكيل؛ فما أنت عليهم بمسيطر؛ فأدِّ ما عليك من الدعوة، ووكِّل أمرَ الهدايةِ إلى الله؛ فلا تذهب نفسك عليهم حسرات؛ فالله حفيظٌ عليهم، وهو الذي يهديهم أو يجازيهم."}},{"n":7,"reflection":{"text":"«وكذلك أوحينا إليك قرآنا عربيا لتنذر أم القرى ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنة وفريق في السعير»، وكذلك أوحينا إليك قرآنًا عربيًّا لتنذر مكّةَ ومن حولها، وتنذر يومَ الجمع (القيامة) لا ريب فيه، فريقٌ في الجنّة وفريقٌ في النار؛ ففي هذا بيانُ وظيفةِ القرآنِ في الإنذار وانقسامِ الناسِ فريقين؛ فاتّعظ بإنذارِ القرآن، واعمل لتكون من فريقِ الجنّة، فالناسُ يومَ القيامةِ فريقان، فاختر لنفسك فريقَ الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بإنذارِ القرآن، والعملُ لتكون من فريقِ الجنّة."},"action":{"text":"تأمّل وظيفةَ القرآنِ في الإنذار: وكذلك أوحينا إليك يا محمدُ قرآنًا عربيًّا بلسانٍ عربيٍّ مبين، لتنذر أمَّ القرى، مكّةَ، ومن حولها من سائرِ الناس، ولتنذر يومَ الجمعِ، يومَ القيامةِ الذي يُجمَع فيه الأوّلون والآخرون، لا ريبَ فيه؛ الناسُ فيه فريقان: فريقٌ في الجنّة، وفريقٌ في السعيرِ والنار «وكذلك أوحينا إليك قرآنا عربيا لتنذر أم القرى ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنة وفريق في السعير»؛ ففي هذا بيانُ وظيفةِ القرآنِ في الإنذار، وانقسامِ الناسِ يومَ القيامةِ فريقين؛ فاتّعظ بإنذارِ القرآنِ وتحذيره؛ واعمل لتكون من فريقِ الجنّةِ لا من فريقِ السعير؛ فالناسُ يومَ القيامةِ فريقان لا ثالثَ لهما: فريقٌ في الجنّةِ وفريقٌ في النار؛ فاختر لنفسك أيَّ الفريقين تكون؛ فاعمل عملَ أهلِ الجنّةِ من الإيمانِ والتقوى والطاعة؛ واجتنب عملَ أهلِ النارِ من الكفرِ والمعاصي؛ فيومَ الجمعِ حقٌّ لا ريبَ فيه؛ فاستعدّ له بالعملِ الصالح؛ فمن اتّعظ بالإنذارِ وعمل صالحًا كان من فريقِ الجنّة."}},{"n":8,"reflection":{"text":"«ولو شاء الله لجعلهم أمة واحدة ولكن يدخل من يشاء في رحمته والظالمون ما لهم من ولي ولا نصير»، ولو شاء الله لجعل الناسَ أمّةً واحدةً على الهدى، لكنه يدخل من يشاء في رحمته، والظالمون ما لهم وليٌّ ولا نصير؛ ففي هذا بيانُ مشيئةِ الله في الهدايةِ وحرمانِ الظالمين؛ فاطلب أن تكون ممّن يدخلهم الله في رحمته بالإيمانِ والطاعة، واحذر الظلمَ الذي يحرم من الولايةِ والنصرة، فالظالمُ لا وليَّ له ولا نصير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ دخولِ رحمةِ الله بالإيمان، والحذرُ من الظلمِ الحارمِ منها."},"action":{"text":"تأمّل مشيئةَ الله في الهداية: ولو شاء الله لجعل الناسَ كلَّهم أمّةً واحدةً مهتديةً مؤمنة، لكنه بحكمته يدخل من يشاء من عباده في رحمته وجنّته بتوفيقهم للإيمانِ والطاعة؛ والظالمون لأنفسهم بالكفرِ والمعاصي ما لهم من وليٍّ يتولّاهم ولا نصيرٍ ينصرهم من عذابِ الله «ولو شاء الله لجعلهم أمة واحدة ولكن يدخل من يشاء في رحمته والظالمون ما لهم من ولي ولا نصير»؛ ففي هذا بيانُ مشيئةِ الله في الهداية، وحرمانِ الظالمين من الولايةِ والنصرة؛ فاطلب أن تكون ممّن يدخلهم الله في رحمته؛ وذلك بالإيمانِ والطاعةِ والإقبالِ على الله؛ فرحمةُ الله قريبةٌ من المحسنين؛ واحذر الظلمَ، ظلمَ النفسِ بالكفرِ والمعاصي، وظلمَ الغيرِ بالتعدّي، الذي يحرم صاحبه من ولايةِ الله ونصرته؛ فالظالمُ لا وليَّ له ينفعه، ولا نصيرَ له يدفع عنه؛ فاطلب ولايةَ الله ونصرته بالإيمانِ والطاعةِ واجتنابِ الظلم؛ فمن آمن واتّقى دخل في رحمةِ الله وكان من أوليائه، ومن ظلم وكفر حُرِم الولايةَ والنصرة؛ فاجعل نفسك في أهلِ رحمةِ الله، لا في أهلِ الظلمِ المحرومين."}},{"n":9,"reflection":{"text":"«أم اتخذوا من دونه أولياء فالله هو الولي وهو يحيي الموتى وهو على كل شيء قدير»: بل اتّخذوا من دونِ الله أولياء! فالله هو الوليُّ الحقُّ، وهو يحيي الموتى، وهو على كلِّ شيء قدير؛ ففي هذا تقريرُ أنّ الولايةَ الحقّةَ لله وحده؛ فاتّخذ الله وليًّا وحده، فهو الوليُّ القادرُ على كلِّ شيء، ولا تتولَّ عاجزًا لا يملك شيئًا، فمن اتّخذ الله وليًّا كفاه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ الله وليًّا وحده، فهو الوليُّ القادرُ على كلِّ شيء."},"action":{"text":"تأمّل تقريرَ الولايةِ الحقّة: بل اتّخذ المشركون من دونِ الله أولياءَ يتولّونهم ويعبدونهم! والحقُّ أنّ الله هو الوليُّ الحقُّ الذي يتولّى عباده المؤمنين بالحفظِ والنصرةِ والتوفيق؛ وهو الذي يحيي الموتى فيبعثهم للجزاء؛ وهو على كلِّ شيء قدير «أم اتخذوا من دونه أولياء فالله هو الولي وهو يحيي الموتى وهو على كل شيء قدير»؛ ففي هذا تقريرُ أنّ الولايةَ الحقّةَ لله وحده، وأنه القادرُ على كلِّ شيء؛ فكيف يُتّخَذ وليٌّ من دونِ الله وهو عاجزٌ لا يملك شيئًا؟ والله هو الوليُّ القادرُ على كلِّ شيء؛ فاتّخذ الله وليًّا وحده؛ فهو الوليُّ الذي يتولّى أمرك، ويحفظك، وينصرك، ويكفيك؛ الله وليُّ الذين آمنوا؛ ولا تتولَّ عاجزًا لا يملك لك ضرًّا ولا نفعًا؛ فمن اتّخذ الله وليًّا كفاه وحفظه ونصره؛ فوالِ الله ورسولَه والمؤمنين؛ وتبرّأ من ولايةِ الكافرين والمعبوداتِ الباطلة؛ فمن كان الله وليّه فاز، ومن تولّى غيره خُذِل؛ فاجعل ولايتك لله وحده؛ فهو الوليُّ القادرُ على كلِّ شيء، المحيي للموتى، الكافي لمن تولّاه."}}]},{"title":"ردُّ المختلَفِ فيه إلى الله، وعظمةُ الخلقِ والتنزيهِ والرزق","range":[10,12],"theme":"أنّ ما اختُلِف فيه يُردّ حكمه إلى الله والتوكّلُ عليه والإنابةُ إليه، وأنه فاطرُ السماواتِ والأرضِ جعل الأزواجَ ليكثّر الخلق، وأنه ليس كمثله شيء وهو السميعُ البصير، وأنّ له مقاليدَ السماواتِ والأرضِ يبسط الرزقَ ويقدر بعلمه","verses":[{"n":10,"reflection":{"text":"«وما اختلفتم فيه من شيء فحكمه إلى الله ذلكم الله ربي عليه توكلت وإليه أنيب»، وما اختلفتم فيه من شيءٍ فحكمه إلى الله (كتابِه)، ذلكم الله ربّي عليه توكّلت وإليه أنيب؛ ففي هذا الأمرُ بردِّ المختلَفِ فيه إلى الله والتوكّلِ عليه؛ فردَّ ما اختلف فيه الناسُ إلى حكمِ الله وكتابه، وتوكّل على الله وأنب إليه، فالحكمُ لله والمرجعُ إليه، فحكّم الله في خلافك وتوكّل عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ المختلَفِ فيه إلى حكمِ الله، والتوكّلُ عليه والإنابةُ إليه."},"action":{"text":"تأمّل الأمرَ بردِّ الخلافِ إلى الله: وما اختلفتم فيه أيها الناسُ من أمورِ الدينِ وغيرها من شيءٍ، فحكمه وفصله إلى الله وإلى كتابه وسنّةِ رسوله؛ ذلكم الحاكمُ العدلُ هو الله ربّي، عليه وحده توكّلت واعتمدت، وإليه أنيب وأرجع بالتوبةِ والطاعة «وما اختلفتم فيه من شيء فحكمه إلى الله ذلكم الله ربي عليه توكلت وإليه أنيب»؛ ففي هذا الأمرُ بردِّ المختلَفِ فيه إلى حكمِ الله، والأمرُ بالتوكّلِ عليه والإنابةِ إليه؛ فإذا اختلف الناسُ في أمرٍ فاردده إلى حكمِ الله وكتابه وسنّةِ رسوله؛ فإن تنازعتم في شيءٍ فردّوه إلى الله والرسول؛ فالحكمُ لله وحده، والمرجعُ إليه؛ فاجعل الله حكمك في كلِّ خلاف؛ ولا تحكّم الهوى ولا العادةَ ولا آراءَ الرجال؛ بل حكّم الوحيَ؛ وتوكّل على الله في جميعِ أمورك؛ فالتوكّلُ اعتمادُ القلبِ على الله في جلبِ النفعِ ودفعِ الضرّ؛ وأنب إلى الله بالرجوعِ إليه بالتوبةِ والطاعةِ في كلِّ حال؛ فاجمع بين تحكيمِ الله والتوكّلِ عليه والإنابةِ إليه؛ فمن حكّم الله وتوكّل عليه وأناب إليه فقد اهتدى؛ فاجعل هذه الثلاثَ منهجك: تحكيمَ الوحي، والتوكّلَ على الله، والإنابةَ إليه."},"qadiyya":{"title":"قضيّةُ ما لم يُؤمَر بردّه","question":"قال الله: ﴿وما اختلفتم فيه من شيء فحكمه إلى الله ذلكم الله ربّي عليه توكّلت وإليه أنيب﴾.\nفالأمرُ بالردّ **لم يقع مطلقًا، بل وقع على قيد**: ﴿ما اختلفتم فيه﴾.\nوليس في الآية ذكرٌ لحكم ما لم يقع فيه اختلاف.\nفالقضيّة: ما الذي يدخل في الاختلاف المأمور بردّه، وإلى أيّ شيء يُردّ؟ ثمّ: **ما حكمُ ما اتّفقت عليه الأمّة، وكيف يُؤخذ من آيةٍ لم تذكره؟** ثمّ: لمَ قرن بين التوكّل والإنابة حتّى جعلهما أصلين لا يتمّ كمال العبد إلّا بهما؟","background":"وقبل الجواب يحتاج القارئُ إلى تقرير جهةٍ في دلالة اللفظ:\nفاللفظُ يدلّ على ما نطق به، ويدلّ أيضًا على حال ما سكت عنه إذا عُلّق حكمُه بقيد.\n**فإذا عُلّق الأمرُ بوصفٍ، فُهم أنّ ما خرج عن الوصف لم يدخل في الأمر.**\nومن قال لأهل بيته: ما اختلفتم فيه فارفعوه إليّ، فقد أفهمهم أنّ ما اتّفقوا عليه لا يُرفع.\nفالأمرُ في الآية معلّقٌ بالاختلاف، فبقي حكمُ الاتّفاق مسكوتًا عنه في اللفظ، مدلولًا عليه بالقيد.","what_happened":"عمّم السعديُّ الاختلافَ المذكور، ففسّر ﴿وما اختلفتم فيه من شيء﴾ بأنّه «من أصول دينكم وفروعه، مما لم تتفقوا عليه».\nثمّ بيّن جهة الردّ في ﴿فحكمه إلى الله﴾: «يرد إلى كتابه، وإلى سنة رسوله، فما حكما به فهو الحق، وما خالف ذلك فباطل».\nثمّ وصل الحكم بالربوبيّة عند ﴿ذلكم الله ربّي﴾: «أي: فكما أنه تعالى الرب الخالق الرازق المدبر، فهو تعالى الحاكم بين عباده بشرعه في جميع أمورهم».\n⭐ ثمّ لم يقف عند المنطوق، بل **صرّح بالمفهوم**: «ومفهوم الآية الكريمة، أن اتفاق الأمة حجة قاطعة، لأن اللّه تعالى لم يأمرنا أن نرد إليه إلا ما اختلفنا فيه».\nثمّ وصل به قوله: «فما اتفقنا عليه، يكفي اتفاق الأمة عليه، لأنها معصومة عن الخطأ، ولا بد أن يكون اتفاقها موافقا لما في كتاب اللّه وسنة رسوله».\nثمّ رجع إلى بقيّة الآية، ففسّر ﴿عليه توكّلت﴾: «أي: اعتمدت بقلبي عليه في جلب المنافع ودفع المضار، واثقا به تعالى في الإسعاف بذلك». وفسّر ﴿وإليه أنيب﴾: «أي: أتوجه بقلبي وبدني إليه، وإلى طاعته وعبادته».\nثمّ جمعهما فقال: «وهذان الأصلان، كثيرا ما يذكرهما اللّه في كتابه، لأنهما يحصل بمجموعهما كمال العبد، ويفوته الكمال بفوتهما أو فوت أحدهما»، واستشهد بقوله ﴿إيّاك نعبد وإيّاك نستعين﴾ وقوله ﴿فاعبده وتوكّل عليه﴾.","the_verdict":"فالحاصلُ أنّ الإمام **استخرج أصلًا من أصول الاستدلال من قيدٍ في الآية**، لا من نصٍّ مستقلٍّ في الباب.\n⭐ وموضعُ الدقّة أنّه لم يدّعِ المفهوم دعوى، بل ردّه إلى صيغة الأمر نفسها: فالأمرُ إنّما تناول محلّ الاختلاف، فبقي ما عداه خارجًا عنه.\nثمّ علّل كفايةَ الاتّفاق بعصمة الأمّة عن الخطأ، ثمّ أتبع ذلك بأنّ اتّفاقها لا بدّ أن يكون موافقًا للكتاب والسنّة. **وظاهرُ ترتيبه أنّ الموافقة لازمٌ من العصمة، لا شرطٌ يُمتحن به الاتّفاق**؛ فالأصلُ عنده مأخوذٌ من الآية، معلّلٌ بالعصمة، ولازمُه الموافقةُ للكتاب والسنّة.\nوسعةُ الاختلاف عنده تتناول الأصول والفروع، **ولازمُ ذلك عندنا أنّ الردّ ليس بابًا للاعتقاد وحده**. والآيةُ ذكرت الله، وجعل الإمامُ الردَّ إليه ردًّا إلى كتابه وسنّة رسوله معًا.\n⭐ وأمّا موضعُ الغلط عند من لم ينتبه للقيد، فثلاثةٌ عندي:\nالأوّل: أن يُتّخذ الأمرُ بالردّ ذريعةً إلى إعادة فتح كلّ مسألة، حتّى ما استقرّ عليه اتّفاق الأمّة؛ فيصير الدينُ مبتدَأً في كلّ جيل.\nوالثاني: أن يُظنّ الاتّفاقُ أصلًا مستقلًّا عن الكتاب والسنّة؛ **وكلامُ الإمام يأبى ذلك، إذ لا يكون اتّفاقُها إلّا موافقًا لهما**.\nوالثالث: أن تُدّعى موافقةُ الأمّة في مسألةٍ الخلافُ فيها واقع؛ فيُسقَط عنها موجبُ الردّ بدعوى لا حقيقة لها.\n⭐ وأمّا قرنُ التوكّل بالإنابة فالذي عنده أنّهما أصلان يحصل بمجموعهما كمال العبد ويفوت بفوت أحدهما. وعندي أنّ في موضعهما بعد تقرير الحكم مناسبةً: **فمن سلّم الحكم لربّه فقد أناب، ومن وثق بكفايته فيه فقد توكّل**.","for_you":"فأمّا الذي تخرج به فثلاثة:\n**الأوّل: افرز المسألة قبل أن تبحثها.** فإذا عرضت لك مسألة فاسأل أوّلًا: أهي ممّا وقع فيه اختلاف، أم ممّا استقرّ عليه أمرُ الأمّة؟ فإنّ الجواب يحدّد لك: أتبحث أم تتّبع.\n**والثاني: اجعل الحَكَم في نزاعك الكتابَ والسنّة.** فعند أوّل خلافٍ يعرض لك اليوم، اطلب الدليل قبل أن تذكر اسم قائل؛ وهذا يُختبر بلسانك في المجلس.\n**والثالث: لا تُطلق دعوى الاتّفاق بلا علم.** فإن أردت أن تقول أجمع أهل العلم، فألزم نفسك أن تُسمّي من نقل الإجماع؛ وإلّا فقل: هذا الذي أعرفه.","grade":"ma'thur","source":"تفسيرُ السعديّ لعموم ﴿ما اختلفتم فيه من شيء﴾ («من أصول دينكم وفروعه»)، وبيانُه جهةَ الردّ («يرد إلى كتابه»)، ووصلُه الحكمَ بالربوبيّة («أي: فكما أنه تعالى الرب»)، وتصريحُه بالمفهوم («ومفهوم الآية الكريمة، أن اتفاق الأمة حجة قاطعة»)، وتعليلُه كفايةَ الاتّفاق وما أتبعه به («فما اتفقنا عليه، يكفي اتفاق الأمة عليه»)، وتفسيرُه ﴿عليه توكّلت﴾ («أي: اعتمدت بقلبي») و﴿وإليه أنيب﴾ («أي: أتوجه بقلبي وبدني»)، وجمعُه بينهما («وهذان الأصلان، كثيرا ما يذكرهما اللّه في كتابه»): كلُّها بنصّها في تفسير السعديّ (٤٢:١٠).","honesty":"وممّا يجب أن يُقال:\n**تقريرُنا في التمهيد لدلالة القيد على المسكوت عنه تمهيدٌ منّا؛** والإمام صرّح بلفظ المفهوم ولم يقرّر القاعدة على هذا الوجه. ومثالُ أهل البيت مثالٌ منّا لتقريبه، ليس في كلامه.\nوأمّا قولُنا إنّ الموافقة للكتاب والسنّة لازمٌ من العصمة لا شرطٌ يُمتحن به الاتّفاق، **فقراءةٌ منّا لترتيب كلامه**؛ والذي له أنّه علّل الكفاية بالعصمة، ثمّ أثبت الموافقة.\nونظمُنا الأصلَ على هذا الوجه ترتيبٌ منّا على كلامه المجموع. ومثلُه قولُنا إنّ الردّ ليس بابًا للاعتقاد وحده، فلازمٌ استخرجناه من تعميمه الأصولَ والفروع.\n**والأغلاطُ الثلاثة استنباطٌ منّا،** لم ينصّ عليها ولا على شيء منها، والثاني منها مبنيٌّ على قراءتنا المتقدّمة لترتيب كلامه.\nوالمناسبةُ التي ذكرناها بعد تقرير الحكم استنباطٌ منّا، ليست في كلامه.\nولم نستوفِ شروط الاتّفاق ومراتبه؛ وما ذكرناه في نقل الإجماع أدبٌ منّا لا تحريرٌ للباب. ومن رأى أنّا وسّعنا فليردّه."}},{"n":11,"reflection":{"text":"«فاطر السماوات والأرض جعل لكم من أنفسكم أزواجا ومن الأنعام أزواجا يذرؤكم فيه ليس كمثله شيء وهو السميع البصير»: خالقُ السماواتِ والأرض، جعل لكم من أنفسكم أزواجًا ومن الأنعامِ أزواجًا، يكثّركم بذلك، ليس كمثله شيء، وهو السميعُ البصير؛ ففي هذا تقريرُ الخلقِ وتنزيهِ الله عن المشابهة؛ فوحّد الخالقَ المنزّهَ عن مشابهةِ خلقه، فمن ليس كمثله شيءٌ يستحقّ العبادةَ وحده، فأخلص له العبادةَ ونزّهه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالق، وتنزيهُه عن مشابهةِ خلقه، وإخلاصُ العبادةِ له."},"action":{"text":"تأمّل عظمةَ الخالقِ وتنزيهه: هو فاطرُ السماواتِ والأرضِ ومبدعهما على غيرِ مثالٍ سابق؛ جعل لكم من أنفسكم أزواجًا، من جنسكم، لتسكنوا إليها، ومن الأنعامِ أزواجًا لمنافعكم؛ يذرؤكم ويكثّركم بهذا التزاوج؛ ليس كمثله شيءٌ في ذاته ولا صفاته ولا أفعاله؛ وهو السميعُ لكلِّ صوت، البصيرُ بكلِّ شيء «فاطر السماوات والأرض جعل لكم من أنفسكم أزواجا ومن الأنعام أزواجا يذرؤكم فيه ليس كمثله شيء وهو السميع البصير»؛ ففي هذا تقريرُ خلقِ الله وتدبيرِه، وتنزيهِه عن مشابهةِ خلقه، وإثباتِ سمعه وبصره؛ فهو الخالقُ المبدعُ للسماواتِ والأرض، الذي جعل الأزواجَ لبقاءِ النسل؛ وهو المنزّهُ عن مشابهةِ المخلوقات في ذاته وصفاته؛ ليس كمثله شيء؛ ومع تنزيهه فهو السميعُ البصير، إثباتُ صفاته الكاملة بلا تشبيهٍ ولا تعطيل؛ فوحّد الخالقَ المنزّهَ عن مشابهةِ خلقه؛ فمن ليس كمثله شيء، وهو الخالقُ السميعُ البصير، يستحقّ العبادةَ وحده؛ فأخلص له العبادة؛ ونزّهه عن كلِّ ما لا يليق به من الشبيهِ والند؛ وأثبت له صفاتِ الكمالِ كما يليق بجلاله؛ فمن عرف الله بأنه ليس كمثله شيءٌ وهو السميعُ البصيرُ وحّده وعظّمه وأخلص له العبادة."}},{"n":12,"reflection":{"text":"«له مقاليد السماوات والأرض يبسط الرزق لمن يشاء ويقدر إنه بكل شيء عليم»: له مفاتيحُ خزائنِ السماواتِ والأرض، يوسّع الرزقَ لمن يشاء ويضيّق، إنه بكلِّ شيء عليم؛ ففي هذا أنّ الرزقَ والخزائنَ بيدِ الله بحكمته وعلمه؛ فاطلب الرزقَ من الله مالكِ الخزائن، واقنع بما قسم لك، فسعةُ الرزقِ وضيقُه بحكمةٍ وعلم، فارضَ بقسمةِ العليمِ الحكيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الرزقِ من الله مالكِ الخزائن، والرضا بقسمته الحكيمة."},"action":{"text":"تأمّل تفرّدَ الله بالخزائنِ والرزق: له وحده مقاليدُ ومفاتيحُ خزائنِ السماواتِ والأرض، فلا يملك خزائنَ الرزقِ والرحمةِ سواه؛ يبسط الرزقَ ويوسّعه لمن يشاء، ويقدر ويضيّقه على من يشاء، بحكمته وعلمه؛ إنه بكلِّ شيء عليم «له مقاليد السماوات والأرض يبسط الرزق لمن يشاء ويقدر إنه بكل شيء عليم»؛ ففي هذا أنّ الرزقَ والخزائنَ بيدِ الله وحده، يدبّرها بحكمته وعلمه؛ فاطلب الرزقَ من الله مالكِ الخزائنِ وحده؛ فلا تسأل إلا من بيده الخزائن؛ واقنع بما قسم الله لك من الرزق؛ فالقناعةُ كنزٌ لا يفنى؛ واعلم أنّ سعةَ الرزقِ وضيقَه بحكمةٍ وعلمٍ من الله، لا لكرامةِ من وُسّع عليه ولا لهوانِ من ضُيّق عليه؛ فارضَ بقسمةِ الله العليمِ الحكيم؛ فمن رضي بما قسم الله له استغنى وسعد، ومن سخط وطمع شقي وتعب؛ فاجعل رزقك على الله؛ واطلبه بالأسبابِ المشروعة؛ وارضَ بعطائه، واشكره على ما آتاك؛ فبيدِه الرزقُ بسطًا وقبضًا بعلمه وحكمته؛ فالعليمُ بكلِّ شيءٍ يعلم ما يصلحك، فيقدّر لك بحكمته."}}]},{"title":"شرعُ الدينِ الواحدِ والنهيُ عن التفرّق، والأمرُ بالدعوةِ والاستقامةِ والعدل","range":[13,16],"theme":"أنّ الله شرع للأمّةِ ما وصّى به نوحًا وإبراهيمَ وموسى وعيسى ومحمدًا: إقامةَ الدينِ وعدمَ التفرّقِ فيه، وأنّ الأممَ ما تفرّقت إلا بغيًا بعد العلم، والأمرُ بالدعوةِ والاستقامةِ وتركِ اتّباعِ الأهواءِ والعدلِ بين الناس، وأنّ المحاجّين في الله بعد الاستجابةِ حجّتهم داحضةٌ وعليهم غضبٌ وعذاب","verses":[{"n":13,"reflection":{"text":"«شرع لكم من الدين ما وصى به نوحا والذي أوحينا إليك وما وصينا به إبراهيم وموسى وعيسى أن أقيموا الدين ولا تتفرقوا فيه كبر على المشركين ما تدعوهم إليه الله يجتبي إليه من يشاء ويهدي إليه من ينيب»: شرع لكم من الدينِ ما وصّى به نوحًا وأوحاه إليك ووصّى به إبراهيمَ وموسى وعيسى: أن أقيموا الدينَ ولا تتفرّقوا فيه؛ كبر على المشركين ما تدعوهم إليه؛ الله يجتبي إليه من يشاء ويهدي إليه من ينيب؛ ففي هذا وحدةُ الدينِ والأمرُ بإقامتِه وعدمِ التفرّق؛ فأقم دينك واجتنب التفرّق، فالدينُ واحدٌ أوصى الله به الأنبياء، فاجتمع على الحقِّ ولا تتفرّق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ الدينِ الواحد، واجتنابُ التفرّقِ فيه."},"action":{"text":"تأمّل هذه الآيةَ الجامعةَ في وحدةِ الدين: شرع الله لكم من الدينِ ما وصّى به نوحًا أوّلَ الرسل، والذي أوحاه إليك يا محمد، وما وصّى به إبراهيمَ وموسى وعيسى، أولي العزمِ من الرسل، ومضمونُ الوصيّة: أن أقيموا الدينَ وحقّقوه، ولا تتفرّقوا فيه؛ كبر وعظُم على المشركين ما تدعوهم إليه من التوحيد؛ الله يجتبي ويصطفي إليه من يشاء من عباده، ويهدي إليه من ينيب ويرجع إليه «شرع لكم من الدين ما وصى به نوحا... أن أقيموا الدين ولا تتفرقوا فيه...»؛ ففي هذا بيانُ وحدةِ أصلِ الدينِ عند جميعِ الأنبياء، والأمرُ بإقامتِه وعدمِ التفرّقِ فيه؛ فأصلُ دينِ الأنبياءِ واحد: التوحيدُ وإخلاصُ العبادةِ لله؛ فأقم الدينَ في نفسك: بتحقيقِ التوحيدِ والعملِ بالشريعة؛ واجتنب التفرّقَ في الدينِ والاختلافَ المذموم؛ ولا تكونوا من المشركين من الذين فرّقوا دينهم وكانوا شيعًا؛ فالتفرّقُ في الدينِ من أعظمِ ما نهى الله عنه؛ فاجتمع مع المؤمنين على الحقِّ والتوحيد؛ واعتصموا بحبلِ الله جميعًا ولا تفرّقوا؛ فالاجتماعُ على الحقِّ رحمة، والتفرّقُ عذاب؛ فاطلب أن يجتبيك الله ويهديك بالإنابةِ إليه؛ فمن أناب إلى الله هداه واجتباه؛ فأنب إلى الله، وأقم الدين، واجتنب التفرّق."}},{"n":14,"reflection":{"text":"«وما تفرقوا إلا من بعد ما جاءهم العلم بغيا بينهم ولولا كلمة سبقت من ربك إلى أجل مسمى لقضي بينهم وإن الذين أورثوا الكتاب من بعدهم لفي شك منه مريب»، وما تفرّق الأممُ إلا من بعد ما جاءهم العلمُ، بغيًا وحسدًا بينهم، ولولا كلمةٌ سبقت بتأخيرِ العذابِ لقُضِي بينهم، وإنّ الذين ورثوا الكتابَ من بعدهم لفي شكٍّ منه مريب؛ ففي هذا بيانُ أنّ سببَ التفرّقِ البغيُ لا الجهل؛ فاحذر البغيَ والحسدَ اللذين يفرّقان الأمّة، واجتمع على الحقِّ، فالتفرّقُ ناشئٌ عن البغيِ بعد العلم، فطهّر قلبك من البغي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من البغيِ والحسدِ المفرّقَين، والاجتماعُ على الحق."},"action":{"text":"تأمّل بيانَ سببِ تفرّقِ الأمم: وما تفرّقت الأممُ السابقةُ في دينها واختلفت إلا من بعد ما جاءهم العلمُ والبيانُ بالحق؛ فتفرّقهم لم يكن عن جهل، بل بغيًا وحسدًا وطلبًا للرياسةِ بينهم؛ ولولا كلمةٌ سبقت من ربّك بتأخيرِ العذابِ إلى أجلٍ مسمًّى لعُجّل لهم العذابُ؛ وإنّ الذين ورثوا الكتابَ من بعدِ أولئك المتفرّقين لفي شكٍّ منه مريبٍ موقعٍ في الريبة «وما تفرقوا إلا من بعد ما جاءهم العلم بغيا بينهم...»؛ ففي هذا بيانُ أنّ سببَ التفرّقِ في الدينِ البغيُ والحسدُ لا الجهل؛ فما تفرّقوا لعدمِ العلم، بل بعد العلمِ بغيًا وحسدًا وطلبًا للدنيا؛ فاحذر البغيَ والحسدَ اللذين يفرّقان الأمّةَ ويمزّقان وحدتها؛ فالبغيُ والحسدُ والتنافسُ على الدنيا من أعظمِ أسبابِ التفرّقِ والاختلاف؛ فطهّر قلبك من البغيِ على إخوانك، ومن الحسدِ لهم، ومن طلبِ العلوِّ عليهم؛ واجتمع مع المؤمنين على الحقِّ والتوحيد؛ ولا تكن سببًا في التفرّقِ والفتنة؛ فمن طلب العلوَّ في الأرضِ والبغيَ فرّق الأمّة؛ ومن تواضع وأخلص جمعها؛ فاحذر أن تكون من المتفرّقين البغاة؛ بل كن من المجتمعين على الحقِّ المتواضعين؛ فبطهارةِ القلبِ من البغيِ والحسدِ تُحفَظ وحدةُ الأمّة."}},{"n":15,"reflection":{"text":"«فلذلك فادع واستقم كما أمرت ولا تتبع أهواءهم وقل آمنت بما أنزل الله من كتاب وأمرت لأعدل بينكم الله ربنا وربكم لنا أعمالنا ولكم أعمالكم لا حجة بيننا وبينكم الله يجمع بيننا وإليه المصير»: فلذلك فادعُ الناسَ إلى الدين، واستقم كما أُمِرت، ولا تتّبع أهواءهم، وقل: آمنت بما أنزل الله من كتاب، وأُمِرت لأعدل بينكم، الله ربّنا وربّكم، لنا أعمالنا ولكم أعمالكم، لا خصومةَ بيننا، الله يجمع بيننا وإليه المصير؛ ففي هذا الأمرُ بالدعوةِ والاستقامةِ والعدلِ وعدمِ اتّباعِ الأهواء؛ فادعُ إلى الحقِّ واستقم عليه، ولا تتّبع الأهواء، واعدل بين الناس، فالاستقامةُ والعدلُ منهجُ الداعية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى الحقِّ والاستقامةُ عليه والعدلُ، وتركُ اتّباعِ الأهواء."},"action":{"text":"تأمّل هذه الوصايا الجامعةَ للنبيِّ ولكلِّ داعية: فلأجلِ هذا الدينِ الحقِّ فادعُ الناسَ إليه؛ واستقم على الدينِ والدعوةِ كما أمرك الله، بلا إفراطٍ ولا تفريط؛ ولا تتّبع أهواءَ المشركين وشهواتهم؛ وقل: آمنت بجميعِ ما أنزل الله من كتاب؛ وأُمِرت لأعدل بينكم في الحكمِ والمعاملة؛ الله ربّنا وربّكم جميعًا؛ لنا أعمالنا ولكم أعمالكم، كلٌّ يُجزى بعمله؛ لا حجّةَ ولا خصومةَ بيننا وبينكم بعد وضوحِ الحق؛ الله يجمع بيننا يومَ القيامةِ فيفصل، وإليه المصيرُ والمرجع «فلذلك فادع واستقم كما أمرت ولا تتبع أهواءهم...»؛ ففي هذا وصايا عظيمةٌ للداعية: الدعوةُ، والاستقامةُ، وتركُ اتّباعِ الأهواء، والإيمانُ بما أنزل الله، والعدل؛ فادعُ إلى الحقِّ والتوحيد؛ واستقم على الدينِ والدعوةِ كما أُمِرت؛ ولا تتّبع أهواءَ الناسِ وشهواتهم في دينك؛ وآمن بجميعِ ما أنزل الله من الكتب؛ واعدل بين الناسِ في حكمك ومعاملتك؛ فالعدلُ ميزانُ الله؛ فاجعل هذه الوصايا منهجك: تدعو إلى الحق، وتستقيم عليه، وتترك الأهواء، وتعدل بين الناس؛ فمن دعا إلى الحقِّ واستقام وعدل وترك الهوى فقد بلغ مقامَ الدعاةِ الصادقين؛ فالاستقامةُ والعدلُ وتركُ الهوى أصولُ الدعوةِ الناجحة."},"qadiyya":{"title":"قضيّةُ «لنا أعمالنا ولكم أعمالكم»: متى ينتهي الجدال؟","question":"أمر اللهُ نبيَّه ﷺ في مخاطبة أهل الكتاب بجملٍ متتابعة: «فلذلك فادعُ واستقم كما أُمرت، ولا تتّبع أهواءهم، وقل آمنتُ بما أنزل اللهُ من كتاب، وأُمرتُ لأعدل بينكم، اللهُ ربّنا وربّكم، لنا أعمالُنا ولكم أعمالُكم، لا حجّة بيننا وبينكم، اللهُ يجمع بيننا وإليه المصير».\nفالقضيّة: لماذا قال ﴿ولا تتّبع أهواءهم﴾ ولم يقل: ولا تتّبع دينهم؟ ثمّ: ما معنى ﴿لا حجّة بيننا وبينكم﴾؟ **أهو نهيٌ عن المناظرة**؟ ثمّ: **ما حدُّ العدل المأمور به مع المخالف**؟","background":"ولا تُفهم دقّةُ اللفظ حتى نُثبت أمرًا:\nدينُ الله الذي شرعه لأهل الكتاب في زمانهم هو دينُ الرسل كلِّهم في أصله.\nفلو قيل للنبيّ ﷺ: لا تتّبع دينهم، **لأوهم ذمَّ ما أنزله اللهُ على موسى وعيسى**.\nوالذي وقع منهم أنّهم تركوا ما شُرع لهم واتّبعوا ما أحدثوه.\nفصار المذمومُ هو **ما أحدثوا لا ما أُنزل إليهم**.\nومن هنا جاء اختيارُ لفظ «الأهواء».","what_happened":"فسّر السعديُّ الاستقامة المأمور بها: «أي: استقامةٌ موافقةٌ لأمر الله، لا تفريط ولا إفراط»، وأنّ الأمر جمع بين أمرين: «فأمره بتكميل نفسه بلزوم الاستقامة، وبتكميل غيره بالدعوة إلى ذلك».\n⭐ ثمّ **قرّر أصلًا في عموم الخطاب**: «ومن المعلوم أنّ أمر الرسول صلّى الله عليه وسلّم أمرٌ لأمّته إذا لم يرد تخصيصٌ له».\n⭐ ثمّ بيّن سرَّ اختيار لفظ «الأهواء» بيانًا صريحًا:\n«ولم يقل: ولا تتّبع دينهم، لأنّ حقيقة دينهم الذي شرعه اللهُ لهم هو دينُ الرسل كلِّهم، ولكنّهم لم يتّبعوه، بل اتّبعوا أهواءهم».\n⭐ ثمّ فسّر ﴿وأُمرت لأعدل بينكم﴾، **وذكر صورةَ العدل مع المخالف**: «أي: في الحكم فيما اختلفتم فيه، فلا تمنعني عداوتُكم وبغضُكم، يا أهل الكتاب، من العدل بينكم»، ثمّ عمّم: «ومن العدل في الحكم بين أهل الأقوال المختلفة، من أهل الكتاب وغيرهم، أن يُقبل ما معهم من الحقّ، ويُردّ ما معهم من الباطل».\n⭐ ثمّ فسّر ﴿لا حجّة بيننا وبينكم﴾: «أي: بعدما تبيّنت الحقائقُ، واتّضح الحقُّ من الباطل، والهدى من الضلال، لم يبقَ للجدال والمنازعة محلّ»، وعلّل: «لأنّ المقصود من الجدال إنّما هو بيانُ الحقّ من الباطل، ليهتديَ الراشد، ولتقوم الحجّةُ على الغاوي».\n⭐ ثمّ **أورد على نفسه ما يُشكل**، وأجاب: «وليس المراد بهذا أنّ أهل الكتاب لا يُجادَلون، كيف واللهُ يقول: ﴿ولا تجادلوا أهل الكتاب إلّا بالتي هي أحسن﴾، وإنّما المراد ما ذكرنا».","the_verdict":"فالحاصلُ ثلاثةُ أمور.\n⭐ فأمّا الأوّل فدقّةُ اللفظ: أنّ المذموم لم يكن ما أُنزل إليهم بل ما أحدثوه.\nوهذا فرقٌ لا يُستهان به في معاملة المخالفين: **أن تُفرّق بين أصل ما ينتسبون إليه وبين ما صاروا عليه**.\nفمن ذمّ الأصلَ أغلق البابَ، و**من ذمّ المحدَث فتح لهم طريقَ الرجوع** إلى أصلهم؛ وأصلُهم يقودهم إلى الحقّ.\n⭐ وأمّا الثاني فحدُّ العدل، وقد صاغه الإمامُ صياغةً جامعة: «أن يُقبل ما معهم من الحقّ، ويُردّ ما معهم من الباطل».\nوهذا هو الأصلُ نفسُه الذي تقدّم في المائدة والحجرات، ويُذكر ها هنا للمرّة الثالثة في موضعٍ ثالث: في المائدة قاعدةً في الشهادة، وفي الحجرات في قبول الخبر، وها هنا في الحكم بين أهل الأقوال.\nفلمّا تكرّر في ثلاثة أبوابٍ **عُلم أنّه أصلٌ لا فرع**.\n⭐ وأمّا الثالث فحدُّ انتهاء الجدال، وهو أنفعُ ما في الموضع.\nفقد عيّن الإمامُ غايةَ الجدال: «بيانُ الحقّ من الباطل، ليهتديَ الراشد، ولتقوم الحجّةُ على الغاوي».\n**فإذا حصلت هذه الغايةُ سقط الجدال**؛ لأنّ الوسيلة تسقط ببلوغ مقصودها.\n**فالمقياسُ إذًا ليس اقتناعَ الخصم**؛ فإنّه قد لا يقتنع أبدًا. إنّما المقياسُ أن يتبيّن الحقُّ.\nوالذي يُواصل بعد أن تبيّن الحقُّ لا يطلب بيانًا؛ إنّما يطلب أن يُقرّ له خصمُه. وذاك لم يُؤمر به.\n⭐ ولاحظ صنيعَه في آخر الموضع: أورد على نفسه أنّ ظاهر كلامه يُوهم منعَ مجادلة أهل الكتاب، ثمّ نقض ذلك بآيةٍ صريحة. وهو الصنيعُ الذي تكرّر منه في يونس ومن غيره في مواضع: أن يُورد ما يُشكل على قوله قبل أن يُورده غيرُه.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: **فرّق بين ما ينتسب إليه المخالف وبين ما صار عليه**. فقد اختير لفظ ﴿أهواءهم﴾ دون «دينهم» لهذا المعنى. وهذا أنفعُ في المحاورة؛ لأنّك إذا هاجمتَ أصلَه دفع عن نفسه، وإذا بيّنتَ أنّه خالف أصلَه لم يجد ما يدفع به.\nوالثاني: اجعل حدَّك في كلّ قول: **أقبل حقَّه وأردّ باطلَه**. فإنّ هذا الأصل تكرّر في ثلاثة أبوابٍ من القرآن، فلم يكن عارضًا. ومن قبل قولًا كلَّه لأجل قائله، أو ردّه كلَّه لأجل قائله، فقد ترك الميزان.\nوالثالث: **اعرف متى تقف**. فغايةُ الجدال أن يتبيّن الحقّ، لا أن يُقرّ خصمُك. فإذا بلغتَ البيانَ فقد أدّيتَ ما عليك، وما بعده ليس دعوةً. وعلامةُ تجاوز الحدّ أن تجد نفسك تُعيد ما قلتَه بألفاظٍ أخرى، لا لتزيد بيانًا، بل لتنتزع اعترافًا.","grade":"ma'thur","source":"تفسيرُ السعديّ للاستقامة («أي: استقامة موافقة لأمر الله، لا تفريط ولا إفراط»، «فأمره بتكميل نفسه بلزوم الاستقامة، وبتكميل غيره بالدعوة إلى ذلك»)، وأصلُه في عموم الخطاب («ومن المعلوم أن أمر الرسول صلى الله عليه وسلم أمر لأمته إذا لم يرد تخصيص له»)، وبيانُه لسرّ اللفظ («ولم يقل: ولا تتبع دينهم لأن حقيقة دينهم الذي شرعه الله لهم، هو دين الرسل كلهم، ولكنهم لم يتبعوه، بل اتبعوا أهواءهم»)، وحدُّه للعدل («ومن العدل في الحكم، بين أهل الأقوال المختلفة، من أهل الكتاب وغيرهم، أن يقبل ما معهم من الحق، ويرد ما معهم من الباطل»)، وتفسيرُه ﴿لا حجة بيننا وبينكم﴾ («أي: بعد ما تبينت الحقائق، واتضح الحق من الباطل، والهدى من الضلال، لم يبق للجدال والمنازعة محل»، «لأن المقصود من الجدال، إنما هو بيان الحق من الباطل، ليهتدي الراشد، ولتقوم الحجة على الغاوي»)، وإيرادُه على نفسه («وليس المراد بهذا أن أهل الكتاب لا يجادلون»): كلُّها بنصّها في تفسير السعديّ (٤٢:١٥).","honesty":"وممّا يجب أن يُقال:\nقولُنا إنّ من ذمّ الأصل أغلق الباب ومن ذمّ المحدَث فتح طريق الرجوع، **فاستنباطٌ منّا** من بيان السعديّ لسرّ اللفظ؛ ومن رأى أنّا وسّعنا فليردّه.\nوأمّا قولُنا إنّ المقياس ليس اقتناع الخصم، فتحريرٌ منّا لتعليل السعديّ في غاية الجدال، لا نصٌّ له.\nوأمّا العلامةُ التي ذكرناها آخرًا (أن تُعيد قولك لتنتزع اعترافًا) **فمن صنيعنا، وليست منصوصةً في كلامه**.\nوقد ذكر السعديُّ في هذا الموضع كلامًا في مناظرة أهل الكتاب وشرطِ التصديق بالقرآن، ولم نبسطه؛ إذ ليس من مقصود هذه الوقفة، وله مظانُّه.\nوالإحالاتُ إلى المائدة ٨ والحجرات ٦ ويونس ٩٤ هي إلى ما تقدّم في مواضعها، بنصوص أصحابها هناك."}},{"n":16,"reflection":{"text":"«والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضة عند ربهم وعليهم غضب ولهم عذاب شديد»، والذين يجادلون في دينِ الله من بعد ما استجاب الناسُ له، حجّتهم باطلةٌ عند ربّهم، وعليهم غضبٌ ولهم عذابٌ شديد؛ ففي هذا وعيدُ المجادلين في الحقِّ بعد ظهوره؛ فاحذر الجدالَ في الحقِّ بعد وضوحه، فحجّةُ المبطلِ داحضةٌ باطلة، فاقبل الحقَّ بعد ظهوره ولا تجادل فيه، فالجدالُ بالباطلِ يوجب الغضبَ والعذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجدالِ في الحقِّ بعد ظهوره، وقبولُه دون معاندة."},"action":{"text":"تأمّل وعيدَ المجادلين في الحق: والذين يحاجّون ويجادلون في دينِ الله وحجّته من بعد ما استجاب الناسُ له ودخلوا فيه وظهر الحق، يريدون ردّه وإطفاءه؛ حجّتهم داحضةٌ باطلةٌ ساقطةٌ عند ربّهم، لا وزنَ لها؛ وعليهم غضبٌ من الله، ولهم عذابٌ شديدٌ في الآخرة «والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضة عند ربهم وعليهم غضب ولهم عذاب شديد»؛ ففي هذا وعيدُ المجادلين في الحقِّ بالباطلِ بعد ظهوره واستجابةِ الناسِ له؛ فمن جادل في الحقِّ بعد وضوحه ليردّه فحجّته باطلةٌ وعليه غضبُ الله؛ فاحذر الجدالَ في الحقِّ بالباطلِ بعد وضوحه وظهوره؛ فإنّ حجّةَ المبطلِ داحضةٌ ساقطةٌ عند الله؛ فاقبل الحقَّ بعد ظهوره واستجب له، ولا تجادل فيه بالباطلِ لتردّه؛ فالجدالُ بالباطلِ في الحقِّ يوجب غضبَ الله والعذابَ الشديد؛ أمّا الجدالُ بالحقِّ لإظهاره ونصرِه فمحمود؛ فلا تكن ممّن يجادل في الحقِّ ليطفئه بعد ظهوره؛ بل كن ممّن يقبله وينصره؛ فمن قبل الحقَّ ونصره فاز، ومن جادل فيه بالباطلِ لردّه خسر واستحقّ الغضبَ والعذاب."}}]},{"title":"إنزالُ الكتابِ والميزان، والساعةُ، ولطفُ الله، وحرثُ الآخرةِ والدنيا","range":[17,20],"theme":"أنّ الله أنزل الكتابَ بالحقِّ والميزانَ وأنّ الساعةَ قريبةٌ يستعجلها المكذّبون ويشفق منها المؤمنون، وأنّ الله لطيفٌ بعباده يرزق من يشاء وهو القويُّ العزيز، وأنّ من أراد حرثَ الآخرةِ زِيد له ومن أراد حرثَ الدنيا أُوتي منها ولا نصيبَ له في الآخرة","verses":[{"n":17,"reflection":{"text":"«الله الذي أنزل الكتاب بالحق والميزان وما يدريك لعل الساعة قريب»: الله الذي أنزل الكتابَ بالحقِّ والعدل، وأنزل الميزانَ لإقامةِ العدل، وما يدريك لعلّ الساعةَ قريبة؛ ففي هذا بيانُ إنزالِ الكتابِ للعدلِ وقربِ الساعة؛ فاتّبع الكتابَ وأقم العدلَ به، واستعدّ للساعةِ فلعلّها قريبة، فالكتابُ حقٌّ والساعةُ قريبة، فاعمل بالكتابِ واستعدّ للقاءِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الكتابِ وإقامةُ العدلِ به، والاستعدادُ للساعةِ القريبة."},"action":{"text":"تأمّل بيانَ إنزالِ الكتابِ والميزان: الله الذي أنزل الكتابَ، القرآنَ وسائرَ الكتب، بالحقِّ والصدقِ والعدل؛ وأنزل الميزانَ، العدلَ الذي تُقام به الحقوق، وآلةَ الوزنِ لإقامةِ العدلِ بين الناس؛ وما يدريك يا محمدُ ويا أيها الإنسان، لعلّ الساعةَ قريبةُ الوقوع «الله الذي أنزل الكتاب بالحق والميزان وما يدريك لعل الساعة قريب»؛ ففي هذا بيانُ أنّ الله أنزل الكتابَ للحقِّ والعدل، والميزانَ لإقامةِ القسط، والتذكيرُ بقربِ الساعة؛ فاتّبع الكتابَ الذي أُنزِل بالحق؛ وأقم العدلَ بين الناسِ بالميزان؛ فالله يأمر بالعدلِ والإحسان؛ ولا تبخسوا الناسَ أشياءهم؛ وأوفوا الكيلَ والميزانَ بالقسط؛ فاعدل في أقوالك وأفعالك وأحكامك ومعاملاتك؛ واستعدّ للساعةِ فلعلّها قريبة؛ فالساعةُ آتيةٌ قريبة، لا يعلم وقتها إلا الله؛ اقتربت الساعةُ؛ فاعمل بالكتابِ، وأقم العدل، واستعدّ للقاءِ الله؛ فمن اتّبع الكتابَ وأقام العدلَ واستعدّ للساعةِ فقد أحسن؛ فاجعل الكتابَ إمامك، والعدلَ منهجك، والاستعدادَ للساعةِ همّك."}},{"n":18,"reflection":{"text":"«يستعجل بها الذين لا يؤمنون بها والذين آمنوا مشفقون منها ويعلمون أنها الحق ألا إن الذين يمارون في الساعة لفي ضلال بعيد»: يستعجل بالساعةِ الذين لا يؤمنون بها استهزاءً، والمؤمنون خائفون منها ويعلمون أنها الحق، ألا إنّ الذين يجادلون في الساعةِ لفي ضلالٍ بعيد؛ ففي هذا الفرقُ بين موقفِ المؤمنِ والكافرِ من الساعة؛ فكن من المؤمنين المشفقين من الساعةِ العالمين أنها حق، واستعدّ لها، ولا تكن من المستهزئين المجادلين فيها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإشفاقُ من الساعةِ والاستعدادُ لها، وتركُ الاستهزاءِ والجدال."},"action":{"text":"تأمّل الفرقَ بين موقفِ المؤمنِ والكافرِ من الساعة: يستعجل بالساعةِ الذين لا يؤمنون بها، استهزاءً وتكذيبًا بوقوعها؛ والذين آمنوا مشفقون خائفون منها ومن أهوالها، ويعلمون أنها الحقُّ الواقعُ لا محالة؛ ألا إنّ الذين يمارون ويجادلون في الساعةِ ويشكّون فيها لفي ضلالٍ بعيدٍ عن الحق «يستعجل بها الذين لا يؤمنون بها والذين آمنوا مشفقون منها ويعلمون أنها الحق ألا إن الذين يمارون في الساعة لفي ضلال بعيد»؛ ففي هذا بيانُ الفرقِ بين موقفِ المؤمنِ والكافرِ من الساعة؛ فالكافرُ يستعجلها استهزاءً وتكذيبًا؛ والمؤمنُ يُشفِق منها ويستعدّ لها ويوقن بها؛ فكن من المؤمنين المشفقين من الساعة، العالمين أنها حقٌّ واقع؛ واستعدّ لها بالإيمانِ والعملِ الصالحِ والتوبة؛ فالإشفاقُ من الساعةِ يحمل على العملِ والاستعداد؛ ولا تكن من المستهزئين المستعجلين المجادلين فيها؛ فإنهم في ضلالٍ بعيد؛ فراقب قلبك: هل تُشفِق من الساعةِ وتستعدّ لها؟ أم تغفل عنها وتستهين بها؟ فاجعل إشفاقك من الساعةِ حافزًا للعملِ والاستعداد؛ فمن أشفق من الساعةِ وعمل لها نجا، ومن استهزأ بها وجادل فيها ضلّ وهلك."}},{"n":19,"reflection":{"text":"«الله لطيف بعباده يرزق من يشاء وهو القوي العزيز»: الله لطيفٌ بعباده يرزق من يشاء، وهو القويُّ العزيز؛ ففي هذا بيانُ لطفِ الله بعباده وقوّته؛ فأحسن الظنَّ بالله اللطيفِ بعباده، فهو يلطف بهم ويرزقهم بحكمته، فاعتمد على لطفِ الله وقوّته، فمن توكّل على اللطيفِ القويِّ كفاه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحسانُ الظنِّ بلطفِ الله بعباده، والاعتمادُ على قوّته."},"action":{"text":"تأمّل لطفَ الله بعباده: الله لطيفٌ بعباده، يوصل إليهم مصالحهم بلطفه وحكمته من حيث لا يشعرون، ويدبّر أمورهم بالخفاءِ واللطف؛ يرزق من يشاء بحكمته وسعةً وضيقًا؛ وهو القويُّ الذي لا يعجزه شيء، العزيزُ الغالبُ الذي لا يُقهَر «الله لطيف بعباده يرزق من يشاء وهو القوي العزيز»؛ ففي هذا بيانُ لطفِ الله بعباده، وسعةِ رزقه، وقوّته وعزّته؛ فالله لطيفٌ بعباده، يدبّر أمورهم بلطفٍ وحكمة، ويسوق إليهم أرزاقهم ومصالحهم من حيث لا يحتسبون؛ فأحسن الظنَّ بالله اللطيفِ بعباده؛ واعلم أنه يلطف بك ويدبّر أمرك بحكمته ورحمته؛ فما يقدّره لك من رزقٍ أو ابتلاءٍ فبلطفه وحكمته؛ فاعتمد على لطفِ الله بك؛ وثق بأنه يدبّر أمرك بما هو خيرٌ لك؛ وهو القويُّ العزيزُ القادرُ على كلِّ شيء؛ فمن توكّل على اللطيفِ القويِّ العزيزِ كفاه؛ فاجعل ثقتك بلطفِ الله وحكمته؛ فكم من أمرٍ ظننته شرًّا فكان فيه لطفُ الله وخيره؛ فأحسن الظنَّ بالله اللطيف؛ وارضَ بتدبيره؛ واعتمد على قوّته وعزّته؛ فاللطيفُ بعباده لا يضيّعهم، والقويُّ العزيزُ لا يعجزه شيءٌ في نصرهم ورزقهم."}},{"n":20,"reflection":{"text":"«من كان يريد حرث الآخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب»: من كان يريد بعمله ثوابَ الآخرةِ نزد له في ثوابه، ومن كان يريد الدنيا نؤته منها وما له في الآخرةِ من نصيب؛ ففي هذا بيانُ أنّ العملَ بالنيّة، وأنّ من عمل للآخرةِ رابح؛ فأخلص عملك للآخرةِ لتنال ثوابها المضاعف، ولا تجعل الدنيا غايتك فتُحرَم الآخرة، فمن أراد الآخرةَ زاده الله، ومن أراد الدنيا وحدها خسر الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إرادةُ الآخرةِ بالعمل، فمن أرادها زاده الله، ومن أراد الدنيا وحدها خسر."},"action":{"text":"تأمّل هذه الآيةَ العظيمةَ في النيّة: من كان يريد بعمله حرثَ الآخرةِ، أي ثوابها ونعيمها، نزد له في حرثه وثوابه، فنضاعف له الحسنات؛ ومن كان يريد بعمله حرثَ الدنيا، حظّها العاجل، نؤته منها ما قُدّر له، وما له في الآخرةِ من نصيبٍ ولا حظّ «من كان يريد حرث الآخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب»؛ ففي هذا بيانُ أنّ الأعمالَ بالنيّاتِ ومقاصدها، وأنّ من عمل للآخرةِ رابحٌ ومن عمل للدنيا وحدها خاسر؛ فمن أراد بعمله الآخرةَ زاده الله وضاعف له؛ ومن أراد بعمله الدنيا وحدها أعطاه منها ما قُدّر، وحُرِم الآخرة؛ فأخلص عملك للآخرةِ ولوجهِ الله؛ لتنال ثوابها المضاعف؛ فمن كان يريد العاجلةَ عجّلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم؛ ومن أراد الآخرةَ وسعى لها سعيها وهو مؤمنٌ فأولئك كان سعيهم مشكورًا؛ فلا تجعل الدنيا غايةَ عملك فتُحرَم الآخرة؛ بل اجعل الآخرةَ نيّتك وغايتك؛ فراقب نيّتك في أعمالك: أللآخرةِ تعمل أم للدنيا؟ فأخلص النيّةَ لله والآخرة؛ فمن أراد الآخرةَ ربح الدارين، ومن أراد الدنيا وحدها خسر الآخرة؛ فاجعل حرثك للآخرةِ الباقية."}}]},{"title":"الشركاءُ المشرّعون، وجزاءُ الظالمين والمؤمنين، والمودّةُ في القربى، وقبولُ التوبة","range":[21,26],"theme":"إنكارُ التشريعِ بغيرِ إذنِ الله ووعيدُ الظالمين، ومقابلةُ إشفاقِ الظالمين بنعيمِ المؤمنين في روضاتِ الجنّاتِ وهو الفضلُ الكبير، وبشارةُ المؤمنين ونزاهةُ النبيِّ عن الأجرِ إلا المودّةَ في القربى ومضاعفةُ الحسنات، وردُّ فريةِ المشركين وأنّ الله يمحو الباطلَ ويحقّ الحق، وأنه يقبل التوبةَ ويعفو عن السيّئاتِ ويستجيب للمؤمنين ويزيدهم من فضله","verses":[{"n":21,"reflection":{"text":"«أم لهم شركاء شرعوا لهم من الدين ما لم يأذن به الله ولولا كلمة الفصل لقضي بينهم وإن الظالمين لهم عذاب أليم»: بل ألهم شركاءُ شرعوا لهم من الدينِ ما لم يأذن به الله؟ ولولا كلمةٌ سبقت بتأخيرِ العذابِ لقُضِي بينهم، وإنّ الظالمين لهم عذابٌ أليم؛ ففي هذا إنكارُ التشريعِ بغيرِ إذنِ الله؛ فاحذر أن تتّبع دينًا لم يأذن به الله، فالتشريعُ حقُّ الله وحده، فلا تحلّل ولا تحرّم إلا بما شرعه الله، فمن شرع دينًا لم يأذن به الله فقد ظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ ما شرعه الله وحده، والحذرُ من التشريعِ بغيرِ إذنه."},"action":{"text":"تأمّل إنكارَ الله على المشركين: بل ألهؤلاء المشركين شركاءُ من شياطينهم وكبرائهم شرعوا لهم من الدينِ ما لم يأذن به الله، من الشركِ وتحليلِ الحرامِ وتحريمِ الحلال؟ ولولا كلمةُ الفصلِ السابقةُ بتأخيرِ العذابِ إلى أجلٍ مسمًّى لعُجّل لهم العذابُ؛ وإنّ الظالمين لهم عذابٌ أليمٌ في الآخرة «أم لهم شركاء شرعوا لهم من الدين ما لم يأذن به الله ولولا كلمة الفصل لقضي بينهم وإن الظالمين لهم عذاب أليم»؛ ففي هذا إنكارُ التشريعِ في الدينِ بغيرِ إذنِ الله؛ فمن شرع دينًا لم يأذن به الله فقد نصّب نفسه شريكًا لله في التشريع؛ فاحذر أن تتّبع دينًا أو حكمًا أو شرعًا لم يأذن به الله؛ فالتشريعُ، التحليلُ والتحريمُ ووضعُ الأحكام، حقٌّ خالصٌ لله وحده؛ إن الحكمُ إلا لله؛ فلا تحلّل ولا تحرّم إلا بما شرعه الله في كتابه وسنّةِ رسوله؛ ولا تتّبع من يشرّع في الدينِ ما لم يأذن به الله؛ اتّخذوا أحبارهم ورهبانهم أربابًا من دونِ الله؛ فمن أطاع مخلوقًا في تحليلِ حرامٍ أو تحريمِ حلالٍ فقد اتّخذه ربًّا؛ فاحذر ذلك؛ والزم ما شرعه الله؛ فمن شرع دينًا لم يأذن به الله فقد ظلم واستحقّ العذابَ الأليم؛ فاتّبع شرعَ الله وحده؛ فهو الدينُ الحق."}},{"n":22,"reflection":{"text":"«ترى الظالمين مشفقين مما كسبوا وهو واقع بهم والذين آمنوا وعملوا الصالحات في روضات الجنات لهم ما يشاءون عند ربهم ذلك هو الفضل الكبير»: ترى الظالمين خائفين من جزاءِ ما كسبوا وهو واقعٌ بهم، والمؤمنون العاملون الصالحاتِ في رياضِ الجنّات، لهم ما يشاؤون عند ربّهم، ذلك هو الفضلُ الكبير؛ ففي هذا مقابلةُ خوفِ الظالمين بنعيمِ المؤمنين؛ فاعمل صالحًا مع الإيمانِ لتكون في روضاتِ الجنّاتِ آمنًا، ولا تكن من الظالمين الخائفين، فالمؤمنون في نعيمٍ والظالمون في خوف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ مع الإيمان، لتكون في نعيمِ الجنّةِ آمنًا لا خائفًا."},"action":{"text":"تأمّل مقابلةَ حالِ الفريقين: ترى الظالمين يومَ القيامةِ مشفقين خائفين من جزاءِ ما كسبوا من الكفرِ والمعاصي، وهو واقعٌ بهم لا محالة، لا ينفعهم خوفهم؛ والذين آمنوا وعملوا الصالحاتِ في روضاتِ الجنّاتِ ورياضها الناعمة، لهم ما يشاؤون ويشتهون عند ربّهم؛ ذلك النعيمُ هو الفضلُ الكبيرُ من الله «ترى الظالمين مشفقين مما كسبوا وهو واقع بهم والذين آمنوا وعملوا الصالحات في روضات الجنات لهم ما يشاءون عند ربهم ذلك هو الفضل الكبير»؛ ففي هذا مقابلةُ خوفِ الظالمين يومَ القيامةِ بنعيمِ المؤمنين وأمنهم؛ فالظالمون خائفون من جزاءِ أعمالهم؛ والمؤمنون العاملون في نعيمِ الجنّةِ آمنون، لهم ما يشتهون؛ فاعمل صالحًا مع الإيمانِ لتكون في روضاتِ الجنّاتِ آمنًا ناعمًا؛ ولا تكن من الظالمين الخائفين من جزاءِ أعمالهم؛ فالمؤمنون في نعيمٍ وأمن، والظالمون في خوفٍ وعذاب؛ فاختر لنفسك أيَّ الفريقين تكون؛ فاعمل عملَ المؤمنين من الإيمانِ والعملِ الصالح؛ لتنال هذا الفضلَ الكبير: روضاتِ الجنّاتِ وما تشتهيه النفوس؛ فالفضلُ الكبيرُ نعيمُ الجنّةِ الذي لا يُنال إلا بالإيمانِ والعملِ الصالح؛ فاطلبه بأسبابه؛ فمن آمن وعمل صالحًا فاز بالفضلِ الكبير."}},{"n":23,"reflection":{"text":"«ذلك الذي يبشر الله عباده الذين آمنوا وعملوا الصالحات قل لا أسألكم عليه أجرا إلا المودة في القربى ومن يقترف حسنة نزد له فيها حسنا إن الله غفور شكور»: ذلك الفضلُ الذي يبشّر الله به عباده المؤمنين العاملين، قل: لا أسألكم عليه أجرًا إلا المودّةَ في القربى (أو التقرّبَ إلى الله بالطاعة)، ومن يعمل حسنةً نزد له فيها حسنًا، إنّ الله غفورٌ شكور؛ ففي هذا بشارةُ المؤمنين ونزاهةُ النبيِّ عن الأجرِ ومضاعفةُ الحسنات؛ فاعمل الحسناتِ لتُضاعَف لك، وأحبّ أهلَ بيتِ النبيِّ، فالله غفورٌ للذنوبِ شكورٌ للطاعات.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عملُ الحسناتِ رجاءَ مضاعفتها، ومحبّةُ أهلِ بيتِ النبيّ."},"action":{"text":"تأمّل بشارةَ المؤمنين وما بعدها: ذلك الفضلُ الكبيرُ هو الذي يبشّر الله به عباده الذين آمنوا وعملوا الصالحات؛ قل يا محمد: لا أسألكم على تبليغِ الرسالةِ أجرًا، إلا أن تودّوني لقرابتي منكم فلا تؤذوني، أو إلا أن تتقرّبوا إلى الله بالطاعةِ والمودّةِ فيه؛ ومن يقترف ويكتسب حسنةً نزد له فيها حسنًا بمضاعفةِ الأجر؛ إنّ الله غفورٌ للذنوب، شكورٌ للطاعاتِ يجازي عليها ويضاعفها «ذلك الذي يبشر الله عباده الذين آمنوا وعملوا الصالحات قل لا أسألكم عليه أجرا إلا المودة في القربى ومن يقترف حسنة نزد له فيها حسنا إن الله غفور شكور»؛ ففي هذا بشارةُ المؤمنين، ونزاهةُ النبيِّ عن طلبِ الأجر، ومضاعفةُ الحسنات، وصفةُ الله بالمغفرةِ والشكر؛ فاعمل الحسناتِ لتُضاعَف لك عند الله؛ فمن جاء بالحسنةِ فله عشرُ أمثالها؛ فالله غفورٌ يغفر الذنوب، شكورٌ يقبل اليسيرَ من العملِ ويجزي عليه الكثير؛ وأحبّ أهلَ بيتِ النبيِّ ﷺ وقرابته؛ فمحبّتهم من الدين؛ ووقّرهم وأدِّ حقّهم؛ واجعل عملك خالصًا لله لا تطلب عليه أجرًا من الناس؛ فاعمل الحسنات، وأحبّ آلَ النبيِّ، وارجُ مغفرةَ الغفورِ وجزاءَ الشكور؛ فمن أحسن ضاعف الله له، ومن تاب غفر له."}},{"n":24,"reflection":{"text":"«أم يقولون افترى على الله كذبا فإن يشإ الله يختم على قلبك ويمح الله الباطل ويحق الحق بكلماته إنه عليم بذات الصدور»: بل أيقولون افترى محمدٌ على الله كذبًا؟ فإن يشأ الله يختم على قلبك، ويمحُ الله الباطلَ ويحقّ الحقَّ بكلماته، إنه عليمٌ بما في الصدور؛ ففي هذا ردُّ فريتهم وتقريرُ نصرةِ الحق؛ فاعلم أنّ الله يمحو الباطلَ ويحقّ الحقَّ، فاثبت على الحقِّ واثقًا بنصرِ الله له، فالحقُّ منصورٌ والباطلُ ممحوقٌ بإذنِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يمحو الباطلَ ويحقّ الحق، والثباتُ على الحق."},"action":{"text":"تأمّل ردَّ الله على فريةِ المشركين: بل أيقول المشركون: افترى محمدٌ على الله كذبًا وتقوّل القرآنَ من عنده؟ فردّ الله عليهم: فإن يشأ الله يختم على قلبك يا محمد لو افتريت عليه، وهذا محالٌ لعصمته، تنبيهًا على أنه لا يفتري؛ ويمحُ الله الباطلَ ويزيله، ويحقّ الحقَّ ويثبّته بكلماته وآياته؛ إنه عليمٌ بما في الصدورِ من النيّاتِ والخفايا «أم يقولون افترى على الله كذبا فإن يشإ الله يختم على قلبك ويمح الله الباطل ويحق الحق بكلماته إنه عليم بذات الصدور»؛ ففي هذا ردُّ فريةِ المشركين، وتقريرُ أنّ الله يمحو الباطلَ ويحقّ الحق؛ فاعلم أنّ الله يمحو الباطلَ ويزيله مهما انتفش، ويحقّ الحقَّ ويثبّته وينصره بكلماته وآياته؛ بل نقذف بالحقِّ على الباطلِ فيدمغه فإذا هو زاهق؛ وقل جاء الحقُّ وزهق الباطل؛ فاثبت على الحقِّ واثقًا بنصرِ الله له؛ فالحقُّ منصورٌ ولو بعد حين، والباطلُ ممحوقٌ ولو انتفش؛ فلا يهولنّك ظهورُ الباطلِ حينًا؛ فإنّ الله يمحوه ويحقّ الحق؛ فاعمل للحقِّ، وانصره، واثبت عليه؛ واعلم أنّ الله عليمٌ بما في صدرك؛ فأخلص لله، وراقبه في سرّك؛ فمن ثبت على الحقِّ نصره الله، ومن اتّبع الباطلَ محقه الله."},"qadiyya":{"title":"قضيّةُ حجّةٍ في صورة وعيد","question":"قال الله: ﴿أم يقولون افترى على الله كذبا فإن يشإ الله يختم على قلبك ويمح الله الباطل ويحق الحق بكلماته إنه عليم بذات الصدور﴾.\nفالتهمةُ منهم، **وظاهرُ اللفظ أنّ الجواب جاء في صورة وعيدٍ للنبيّ لا لهم**: ﴿فإن يشإ الله يختم على قلبك﴾.\nفالقضيّة: ما وجهُ اتّصال هذا بتكذيبهم؟ ثمّ: كيف تصير القدرةُ على الختم شهادةً على الصدق؟ ثمّ: ما معنى أن يكون قيامُ الباطل من جملة إحقاق الحقّ؟","background":"ولا يظهر موضعُ الجواب حتى يتقدّم أمران:\nالأوّل: أنّ ردّ الدعوى وجهان: إبطالُها بدليلٍ من خارجها، **وإجراؤها على موجبها حتى تهدم نفسها**. والثاني ألزمُ؛ لأنّ الخصم لا ينفكّ عمّا التزمه.\nوالثاني: أنّ قطع الأمر يكون بدفعه بعد وقوعه، ويكون بحسمه من مادّته قبل أن يقع. **ومن ملك المادّة ملك القطع بلا معالجة**؛ فلا يحتاج إلى ردّ ما ظهر، إذ يمنعه أن يظهر.","what_happened":"قرّر السعديُّ أوّلًا شناعة التهمة: «فرموك بأشنع الأمور وأقبحها»، ثمّ ذكر حال قائليها: «وهم يعلمون صدقك وأمانتك».\n⭐ ثمّ نقل القدح من الرسول إلى مَن أرسله، ووصف الدعوة بما يقتضيه زعمُهم: «بل تجرأوا بذلك على الله تعالى، فإنه قدح في الله، حيث مكنك من هذه الدعوة العظيمة، المتضمنة -على موجب زعمهم- أكبر الفساد في الأرض، حيث مكنه الله من التصريح بالدعوة، ثم بنسبتها إليه».\nثمّ عدّ وجوه التأييد بعد التمكين: «ثم يؤيده بالمعجزات الظاهرات، والأدلة القاهرات، والنصر المبين، والاستيلاء على من خالفه».\n⭐ ثمّ قرّر **القدرة على القطع من الأصل**: «وهو تعالى قادر على حسم هذه الدعوة من أصلها ومادتها، وهو أن يختم على قلب الرسول صلى الله عليه وسلم فلا يعي شيئا ولا يدخل إليه خير»، ثمّ قال: «وإذا ختم على قلبه انحسم الأمر كله وانقطع».\nثمّ بنى عليه حكمه: «فهذا دليل قاطع على صحة ما جاء به الرسول، وأقوى شهادة من الله له على ما قال، ولا يوجد شهادة أعظم منها ولا أكبر».\nثمّ عطف على هذه الشهادة بقوله «ولهذا» سنّةً جاريةً مقيّدة: «ولهذا من حكمته ورحمته، وسنته الجارية، أنه يمحو الباطل ويزيله، وإن كان له صولة في بعض الأوقات، فإن عاقبته الاضمحلال».\nثمّ فسّر ﴿ويحق الحق بكلماته﴾ بنوعين: «الكونية، التي لا تغير ولا تبدل، ووعده الصادق، وكلماته الدينية التي تحقق ما شرعه من الحق، وتثبته في القلوب».\n⭐ ثمّ زاد: «حتى إن من جملة إحقاقه تعالى الحق، أن يُقَيِّضَ له الباطل ليقاومه، فإذا قاومه، صال عليه الحق ببراهينه وبيناته، فظهر من نوره وهداه ما به يضمحل الباطل وينقمع، ويتبين بطلانه لكل أحد، ويظهر الحق كل الظهور لكل أحد».\nثمّ ختم بتفسير ﴿إنه عليم بذات الصدور﴾: «أي: بما فيها، وما اتصفت به من خير وشر، وما أكنته ولم تبده».","the_verdict":"والذي يظهر لنا أنّ موضع الحجّة هو **تركُ الحسم مع القدرة عليه**.\nفالخصم ادّعى الافتراء، فأجرى الإمامُ دعواهم على موجبها: لو كانت الدعوة أكبر الفساد لكان الممكِّنُ منها هو الله، وهو القادر على قطعها من مادّتها، «وإذا ختم على قلبه انحسم الأمر كله وانقطع». والذي جرى تمكينٌ ثمّ تأييد؛ فارتدّت الدعوى على صاحبها.\n⭐ ولهذا سمّاه الإمام «أقوى شهادة من الله له»؛ فالتأييدُ الذي عدّه، معجزاتٌ وأدلّةٌ ونصرٌ واستيلاء، أمرٌ واقعٌ لا خبرٌ مقول.\nوأمّا آخرُ الآية فقد عطف فيه سنّة محو الباطل على الشهادة بقوله «ولهذا»؛ فهي تقريرٌ لها لا انتقالٌ عنها، ولم يتعرّض لغير هذا الوجه.\n⭐ وأمّا صولةُ الباطل فقد قيّدها بقيدين لا يُهملان: أنّها «صولة في بعض الأوقات»، وأنّ «عاقبته الاضمحلال». **فالصولةُ مُثبَتةٌ لا منفيّة، والحكمُ على المآل لا على الحال.** فمن جعلها نقضًا للسنّة فقد حكم قبل أوانه.\n⭐ وأدقُّ ما في الموضع أنّه جعل المقاومة نفسها من الإحقاق؛ فالبيّنةُ إنّما تُخرَج عند المنازعة، فلولا أن قام الباطل لبقي من براهين الحقّ ما هو مطويّ، وهذا معنى قوله: «صال عليه الحق ببراهينه وبيناته». ولم يقف عند اضمحلال الباطل، بل ضمّ إليه «ويظهر الحق كل الظهور لكل أحد».","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: **أجرِ دعوى خصمك على موجبها قبل أن تردّها.** فاكتب دعواه في سطر، ثمّ اكتب تحتها ما يلزم منها لو صحّت؛ فكثيرٌ منها يسقط بلازمه.\nوالثاني: **لا تحكم على الحقّ بحال الوقت.** فإذا رأيتَ باطلًا صائلًا فأخّر حكمك؛ فإنّ الإمام أخبر أنّ عاقبة الباطل الاضمحلال، ولم يوقّت للعاقبة أجلًا تراقبه.\nوالثالث: **إن ثبت عندك الحقُّ ببرهانه المستقلّ فلا تعدّ المقاومة نقضًا له.** واكتب ما استُخرج من الأدلّة بسببها ولم يكن ظاهرًا قبلها. وليس هذا حكمًا على كلّ دعوى تُنازَع؛ فالمنازعةُ تقوم على الحقّ والباطل معًا.","grade":"ma'thur","source":"تفسيرُ السعديّ للتهمة («فرموك بأشنع الأمور»)، وإجراؤها على موجب زعمهم («بل تجرأوا بذلك على الله تعالى»)، ووجوهُ التأييد («ثم يؤيده بالمعجزات الظاهرات»)، والقدرةُ على الحسم («وهو تعالى قادر على حسم هذه الدعوة»)، وبناءُ الحكم عليها («فهذا دليل قاطع»)، وسنّةُ المحو بقيدها («ولهذا من حكمته ورحمته»)، ونوعا الكلمات («الكونية، التي لا تغير ولا تبدل»)، وتقييضُ الباطل («حتى إن من جملة إحقاقه تعالى الحق»)، و﴿عليم بذات الصدور﴾ («أي: بما فيها»): كلُّها بنصّها في تفسير السعديّ (٤٢:٢٤).","honesty":"وممّا يجب أن يُقال:\nأمّا إجراءُ الدعوى على موجبها فمنصوصٌ عنده بقوله «على موجب زعمهم»، وإنّما **التسميةُ منّا**. وأمّا التفريقُ بين دفع الأمر بعد وقوعه وحسمه من مادّته فتمهيدٌ منّا.\nوقولُنا إنّ موضع الحجّة تركُ الحسم مع القدرة عليه، **صياغةٌ منّا** لمرجع «فهذا» في قوله «فهذا دليل قاطع»؛ والإمامُ لم يصرّح بالمرجع.\nوقولُنا إنّ آخر الآية تقريرٌ لأوّلها، **ملاحظةٌ منّا** على ترتيب كلامه وموضع «ولهذا» منه.\nوقولُنا إنّ البيّنة إنّما تُخرَج عند المنازعة **استنباطٌ منّا** من قوله في تقييض الباطل؛ وهو عنده في إحقاق الحقّ الذي جاء به الرسول، فلا يُنقل إلى كلّ خصومةٍ بإطلاق.\nوالثلاثةُ التي في آخر القضيّة أعمالٌ رتّبناها نحن؛ ولا عنده تأخيرُ حكمٍ ولا مراقبةُ مدّة، وإنّما أخبر بالعاقبة. ومن رأى أنّا وسّعنا فليردّه."}},{"n":25,"reflection":{"text":"«وهو الذي يقبل التوبة عن عباده ويعفو عن السيئات ويعلم ما تفعلون»، وهو الذي يقبل التوبةَ عن عباده، ويعفو عن السيّئات، ويعلم ما تفعلون؛ ففي هذا بيانُ سعةِ عفوِ الله وقبولِه التوبة؛ فبادر بالتوبةِ إلى الله الذي يقبلها ويعفو عن السيّئات، فباب التوبةِ مفتوح، فمن تاب تاب الله عليه وعفا عنه، فتب واستغفر، والله يعلم عملك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ إلى الله الذي يقبلها ويعفو عن السيّئات."},"action":{"text":"تأمّل سعةَ عفوِ الله وكرمه: وهو الذي يقبل التوبةَ عن عباده إذا تابوا وأنابوا، ويعفو عن السيّئاتِ والذنوبِ فيمحوها، ويعلم ما تفعلون من خيرٍ وشرٍّ فيجازيكم عليه «وهو الذي يقبل التوبة عن عباده ويعفو عن السيئات ويعلم ما تفعلون»؛ ففي هذا بيانُ سعةِ عفوِ الله وكرمه في قبولِ التوبةِ والعفوِ عن السيّئات؛ فالله يقبل توبةَ التائبين، ويعفو عن سيّئاتِ المستغفرين؛ فبادر بالتوبةِ إلى الله الذي يقبلها ويفرح بها؛ فباب التوبةِ مفتوحٌ لا يُغلَق حتى تطلع الشمسُ من مغربها؛ ومن تاب تاب الله عليه وعفا عنه ومحا سيّئاته؛ إنّ الله يحبّ التوّابين؛ ويقبل التوبةَ عن عباده ويعفو عن السيّئات؛ فلا تيأس من رحمةِ الله ومغفرته مهما عظمت ذنوبك؛ فتب واستغفر وأنب إلى الله؛ فإنه يقبل التوبةَ ويعفو عن السيّئات؛ واعلم أنّ الله يعلم ما تفعل؛ فراقبه في عملك؛ فمن تاب صادقًا قبل الله توبته وعفا عن سيّئاته؛ فاجعل التوبةَ والاستغفارَ دأبك؛ فالله يقبل التوبةَ ويعفو ويرحم؛ فبادر بها قبل فواتِ الأوان."}},{"n":26,"reflection":{"text":"«ويستجيب الذين آمنوا وعملوا الصالحات ويزيدهم من فضله والكافرون لهم عذاب شديد»، ويستجيب الله للذين آمنوا وعملوا الصالحاتِ (دعاءهم)، ويزيدهم من فضله، والكافرون لهم عذابٌ شديد؛ ففي هذا استجابةُ الله للمؤمنين ومضاعفةُ فضله؛ فآمن واعمل صالحًا لتُستجاب دعوتك وتُزاد من فضلِ الله، فالله يستجيب للمؤمنين ويزيدهم، فادعُ الله واعمل صالحًا لتنال إجابته وفضله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والعملُ الصالح، رجاءَ استجابةِ الله ومضاعفةِ فضله."},"action":{"text":"تأمّل استجابةَ الله للمؤمنين: ويستجيب الله دعاءَ الذين آمنوا وعملوا الصالحات، ويثيبهم على أعمالهم؛ ويزيدهم من فضله فوق ما يستحقّون بأعمالهم؛ والكافرون لهم عذابٌ شديدٌ في الآخرة «ويستجيب الذين آمنوا وعملوا الصالحات ويزيدهم من فضله والكافرون لهم عذاب شديد»؛ ففي هذا بيانُ استجابةِ الله للمؤمنين العاملين، ومضاعفةِ فضله لهم، ووعيدِ الكافرين؛ فالله يستجيب دعاءَ المؤمنين ويقبل أعمالهم؛ ويزيدهم من فضله وكرمه أضعافًا؛ للذين أحسنوا الحسنى وزيادة؛ فآمن واعمل صالحًا لتكون ممّن يستجيب الله لهم ويزيدهم من فضله؛ فالإيمانُ والعملُ الصالحُ من أسبابِ استجابةِ الدعاءِ ونيلِ الفضل؛ فادعُ الله واعمل صالحًا لتنال إجابته ومزيدَ فضله؛ ولا تكن من الكافرين الذين لهم عذابٌ شديد؛ فاختر لنفسك سبيلَ المؤمنين المستجابِ لهم؛ فمن آمن وعمل صالحًا ودعا الله استجاب له وزاده من فضله؛ فاجعل الإيمانَ والعملَ الصالحَ والدعاءَ زادك؛ فبها تُنال الاستجابةُ والفضلُ والنجاةُ من العذاب."}}]},{"title":"حكمةُ الله في الرزق، وإنزالُ الغيث، وآياتُ الخلق، وأنّ المصائبَ بالكسب","range":[27,31],"theme":"أنّ الله لو بسط الرزقَ لعباده لبغوا فينزّله بقدرٍ بحكمته، وأنه ينزّل الغيثَ بعد القنوطِ وينشر رحمته وهو الوليُّ الحميد، وأنّ من آياته خلقَ السماواتِ والأرضِ وما بثّ فيهما من دابّةٍ وهو قادرٌ على جمعهم، وأنّ ما أصاب العبادَ من مصيبةٍ فبكسبهم ويعفو عن كثير، وأنهم لا يعجزون الله ولا وليَّ لهم ولا نصيرَ من دونه","verses":[{"n":27,"reflection":{"text":"«ولو بسط الله الرزق لعباده لبغوا في الأرض ولكن ينزل بقدر ما يشاء إنه بعباده خبير بصير»، ولو وسّع الله الرزقَ لجميعِ عباده لبغوا وطغوا في الأرض، ولكن ينزّله بقدرٍ ما يشاء بحكمته، إنه بعباده خبيرٌ بصير؛ ففي هذا بيانُ حكمةِ الله في تقديرِ الرزق؛ فاعلم أنّ تضييقَ الرزقِ قد يكون رحمةً وحكمة، فارضَ بتقديرِ الله لرزقك، فمن ضيّق عليه رزقه فبحكمةٍ من الله الخبيرِ بعباده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بتقديرِ الله للرزق، وإدراكُ حكمتِه في بسطِه وقبضه."},"action":{"text":"تأمّل حكمةَ الله في تقديرِ الأرزاق: ولو بسط الله الرزقَ ووسّعه لجميعِ عباده لبغوا وطغوا وأفسدوا في الأرض؛ فالغنى الواسعُ قد يحمل على الطغيان؛ ولكنّ الله بحكمته ينزّل الرزقَ بقدرٍ معلومٍ ما يشاء، لكلٍّ ما يصلحه؛ إنه بعباده خبيرٌ بصير، يعلم ما يصلحهم فيقدّره لهم «ولو بسط الله الرزق لعباده لبغوا في الأرض ولكن ينزل بقدر ما يشاء إنه بعباده خبير بصير»؛ ففي هذا بيانُ حكمةِ الله البالغةِ في تقديرِ الأرزاق؛ فاعلم أنّ تضييقَ الرزقِ على بعضِ العبادِ قد يكون رحمةً بهم وحكمة، لئلا يبغوا ويطغوا؛ كلا إنّ الإنسانَ ليطغى أن رآه استغنى؛ فارضَ بتقديرِ الله لرزقك؛ فما قدّره لك من سعةٍ أو ضيقٍ فبحكمته وعلمه بما يصلحك؛ فمن ضُيّق عليه رزقه فقد يكون ذلك خيرًا له وحفظًا من الطغيان؛ ولا تتمنَّ ما فضّل الله به غيرك؛ فالله أعلمُ بما يصلح عباده؛ فاطمئنّ إلى حكمةِ الله في رزقك؛ واعلم أنه خبيرٌ بصيرٌ بك، يقدّر لك ما يصلحك؛ فارضَ بقسمته، واشكره على ما آتاك، وثق بحكمته فيما قدّر."}},{"n":28,"reflection":{"text":"«وهو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته وهو الولي الحميد»، وهو الذي ينزّل المطرَ من بعد ما يئس الناسُ منه، وينشر رحمته، وهو الوليُّ الحميد؛ ففي هذا بيانُ رحمةِ الله بإنزالِ الغيثِ عند اليأس؛ فلا تيأس من رحمةِ الله، فهو ينزّل الفرجَ والرحمةَ عند اشتدادِ اليأس، فارجُ رحمةَ الله دائمًا، فمن رحمته أن ينزّل الغيثَ بعد القنوط.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ اليأسِ من رحمةِ الله، ورجاؤها ولو عند اشتدادِ القنوط."},"action":{"text":"تأمّل رحمةَ الله بعباده: وهو الذي ينزّل الغيثَ، المطرَ النافع، من بعد ما قنط الناسُ ويئسوا من نزوله؛ وينشر رحمته في الأرضِ فيحيي البلادَ والعباد؛ وهو الوليُّ الذي يتولّى عباده بالرحمةِ والإحسان، الحميدُ المحمودُ على نعمه وأفعاله «وهو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته وهو الولي الحميد»؛ ففي هذا بيانُ رحمةِ الله بإنزالِ الغيثِ بعد اليأس، وولايتِه لعباده؛ فينزّل المطرَ في أحوجِ ما يكونون إليه، بعد أن قنطوا ويئسوا؛ فلا تيأس من رحمةِ الله؛ فهو ينزّل الفرجَ والرحمةَ عند اشتدادِ اليأسِ والقنوط؛ فكما ينزّل الغيثَ بعد القنوط، ينزّل الفرجَ بعد الشدّة، والرحمةَ بعد اليأس؛ فارجُ رحمةَ الله دائمًا، ولا تقنط منها مهما اشتدّ عليك الأمر؛ فإنّ فرجَ الله قريب؛ ولا تيأسوا من روحِ الله؛ فمن رحمةِ الله أن ينزّل الغيثَ والفرجَ عند اشتدادِ الحاجةِ واليأس؛ فأحسن الظنَّ بالله، وارجُ رحمته؛ فهو الوليُّ الحميدُ الذي يتولّى عباده برحمته؛ فاعتمد على ولايته، وارجُ رحمته، ولا تقنط؛ فالله ينشر رحمته على عباده في أحوجِ الأوقات."}},{"n":29,"reflection":{"text":"«ومن آياته خلق السماوات والأرض وما بث فيهما من دابة وهو على جمعهم إذا يشاء قدير»، ومن آياته خلقُ السماواتِ والأرضِ وما نشر فيهما من دوابّ، وهو على جمعهم إذا يشاء قدير؛ ففي هذا الاستدلالُ بالخلقِ على البعث؛ فتأمّل في خلقِ السماواتِ والأرضِ والدوابّ، فمن خلقها وبثّها قادرٌ على جمعها للحساب، فأيقن بالبعثِ واستعدّ له، فالقادرُ على الخلقِ قادرٌ على الجمع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ استدلالًا بخلقِ السماواتِ والأرضِ والدوابّ."},"action":{"text":"تأمّل آياتِ الله في الخلق: ومن آياته الدالّةِ على قدرته ووحدانيّته خلقُ السماواتِ والأرضِ على عظمهما وإحكامهما، وما بثّ ونشر فيهما من دابّةٍ لا يحصيها إلا هو؛ وهو على جمعهم، جمعِ الخلقِ للحسابِ يومَ القيامة، إذا يشاء قدير «ومن آياته خلق السماوات والأرض وما بث فيهما من دابة وهو على جمعهم إذا يشاء قدير»؛ ففي هذا الاستدلالُ بخلقِ السماواتِ والأرضِ والدوابِّ على قدرةِ الله على البعثِ والجمع؛ فتأمّل في خلقِ السماواتِ والأرض، وفيما بثّ فيهما من الدوابِّ المتنوّعةِ التي لا تُحصى؛ فمن خلق هذا الخلقَ العظيم، وبثّ هذه الدوابَّ الكثيرة، قادرٌ على أن يجمعهم للحسابِ متى شاء؛ فالقادرُ على الخلقِ والبثِّ قادرٌ على الجمعِ والبعث؛ فأيقن بالبعثِ والجمعِ يومَ القيامة؛ واستعدّ له بالإيمانِ والعملِ الصالح؛ فمن تأمّل خلقَ الله وبثّه للدوابِّ أيقن بقدرته على جمعهم وبعثهم؛ فاجعل من تأمّلك في خلقِ السماواتِ والأرضِ والدوابِّ دليلًا يقوّي يقينك بالبعثِ ويحملك على الاستعدادِ له؛ فالبعثُ حقٌّ، والجمعُ آتٍ، والقادرُ على الخلقِ قادرٌ عليه."}},{"n":30,"reflection":{"text":"«وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير»، وما أصابكم من مصيبةٍ فبسببِ ما كسبت أيديكم من الذنوب، ويعفو الله عن كثيرٍ من ذنوبكم فلا يعاقب عليها؛ ففي هذا بيانُ أنّ المصائبَ بسببِ الذنوبِ وسعةِ عفوِ الله؛ فإذا أصابتك مصيبةٌ فحاسب نفسك وتب من ذنوبك، واعلم أنّ الله يعفو عن كثير، فاجعل المصائبَ داعيةً للتوبةِ والاستغفار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ عند المصائبِ والتوبةُ من الذنوب، وإدراكُ عفوِ الله."},"action":{"text":"تأمّل بيانَ سببِ المصائب: وما أصابكم من مصيبةٍ في أنفسكم أو أموالكم أو أهليكم فبسببِ ما كسبت أيديكم من الذنوبِ والمعاصي؛ ويعفو الله عن كثيرٍ من ذنوبكم فلا يعاقبكم عليها في الدنيا، فلو آخذكم بكلِّ ذنبٍ ما ترك على ظهرها من دابّة «وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير»؛ ففي هذا بيانُ أنّ المصائبَ إنما تصيب العبدَ بسببِ ذنوبه، وبيانُ سعةِ عفوِ الله؛ فما من مصيبةٍ إلا بذنب، وما يعفو الله عنه أكثر؛ فإذا أصابتك مصيبةٌ، مرضٌ أو فقدٌ أو ضيقٌ أو نقص، فحاسب نفسك، وانظر في ذنوبك، وتب منها إلى الله؛ ولا تلُم إلا نفسك؛ فما أصابك من سيّئةٍ فمن نفسك؛ واجعل المصيبةَ داعيةً للتوبةِ والاستغفارِ والرجوعِ إلى الله؛ فالمصائبُ تكفّر الذنوبَ لمن صبر واحتسب؛ واعلم أنّ الله يعفو عن كثيرٍ من ذنوبك برحمته؛ فاحمده على عفوه، وتب إليه من ذنوبك؛ فمن حاسب نفسه عند المصائبِ وتاب انتفع بها؛ ومن جزع ولم يتّعظ حُرِم خيرها؛ فاجعل المصائبَ مذكّرةً بالذنوبِ داعيةً للتوبة؛ فبالتوبةِ تُكشَف المصائبُ وتُكفَّر الذنوب."}},{"n":31,"reflection":{"text":"«وما أنتم بمعجزين في الأرض وما لكم من دون الله من ولي ولا نصير»، وما أنتم بفائتين من عذابِ الله في الأرض، وما لكم من دونِ الله من وليٍّ ولا نصير؛ ففي هذا بيانُ عجزِ العبادِ عن الفرارِ من الله؛ فاعلم أنك لن تعجز الله ولن تفوته، فالجأ إليه ولا تفرّ منه، فمن اعتمد على غيرِ الله خُذِل، فاطلب ولايةَ الله ونصرته بالإيمانِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ العجزِ عن الفرارِ من الله، وطلبُ ولايتِه ونصرته."},"action":{"text":"تأمّل بيانَ عجزِ العبادِ أمام الله: وما أنتم بمعجزين لله ولا فائتين من عذابه وقدرته في الأرض أينما كنتم؛ وما لكم من دونِ الله من وليٍّ يتولّى أمركم، ولا نصيرٍ ينصركم ويدفع عنكم عذابه «وما أنتم بمعجزين في الأرض وما لكم من دون الله من ولي ولا نصير»؛ ففي هذا بيانُ عجزِ العبادِ عن الفرارِ من الله، وأنه لا وليَّ ولا نصيرَ من دونه؛ فاعلم أنك لن تعجز الله ولن تفوته ولن تسبقه؛ فأينما كنت يدركك أمر الله وقدرته؛ وما أنتم بمعجزين في الأرضِ ولا في السماء؛ فلا مفرَّ من الله إلا إليه؛ فالجأ إلى الله ولا تفرّ منه؛ ولا تعتمد على غيره؛ فمن اعتمد على غيرِ الله خُذِل؛ فما لك من دونِ الله من وليٍّ ينفعك ولا نصيرٍ يدفع عنك؛ فاطلب ولايةَ الله ونصرته بالإيمانِ والطاعةِ والتوكّلِ عليه؛ فالله وليُّ المؤمنين وناصرهم؛ فمن اتّخذ الله وليًّا ونصيرًا كفاه؛ ومن تولّى غيره خُذِل وضاع؛ فاجعل ولايتك وتوكّلك ورجاءك بالله وحده؛ فلا وليَّ ولا نصيرَ سواه؛ فبولايةِ الله ونصرته تُنال النجاةُ والكفاية."}}]},{"title":"آياتُ الفلك، وأنّ ما عند الله خيرٌ وأبقى، وصفاتُ المؤمنين ومنها الشورى","range":[32,39],"theme":"أنّ من آياته الجواريَ في البحرِ وأنها بمشيئته آيةٌ لكلِّ صبّارٍ شكور، وأنّ ما أوتيه الناسُ متاعُ الدنيا وما عند الله خيرٌ وأبقى للمؤمنين المتوكّلين، ثم وصفُ المؤمنين باجتنابِ الكبائرِ والفواحشِ والعفوِ عند الغضبِ والاستجابةِ لله وإقامةِ الصلاةِ وأنّ أمرهم شورى بينهم والإنفاقِ والانتصارِ من البغي","verses":[{"n":32,"reflection":{"text":"«ومن آياته الجوار في البحر كالأعلام»، ومن آياته السفنُ الجاريةُ في البحرِ كالجبالِ العالية؛ ففي هذا الاستدلالُ بجريِ السفنِ على قدرةِ الله ونعمته؛ فتأمّل نعمةَ الله في تسخيرِ البحرِ والسفن، فمن سخّرها لك يستحقّ الشكرَ والعبادة، فاشكر الله على تسخيرِ ما تنتفع به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ تسخيرِ البحرِ والسفن، وتوحيدُ المسخِّر."},"action":{"text":"تأمّل آيةَ الله في البحرِ والسفن: ومن آياته الدالّةِ على قدرته ونعمته الجواري، السفنُ الجاريةُ في البحرِ، كالأعلامِ، أي كالجبالِ العاليةِ في عظمها «ومن آياته الجوار في البحر كالأعلام»؛ ففي هذا الاستدلالُ بجريِ السفنِ العظيمةِ في البحرِ على قدرةِ الله ونعمته؛ فمن سخّر البحرَ لحملِ هذه السفنِ العظيمة، وجعل الماءَ يحملها رغمَ ثقلها، وسخّر الرياحَ لتسييرها؟ إنه الله؛ فتأمّل نعمةَ الله في تسخيرِ البحرِ والسفنِ لمنافعك ونقلك وتجارتك؛ ألله الذي سخّر لكم البحرَ لتجريَ الفلكُ فيه بأمره؛ فمن سخّر البحرَ والسفنَ يستحقّ الشكرَ والعبادةَ والتوحيد؛ فاشكر الله على تسخيرِ ما تنتفع به من البحرِ والسفنِ وسائرِ النعم؛ واستعمل هذه النعمَ في طاعته؛ فمن تأمّل نعمَ الله في تسخيرِ خلقه شكرها ووحّد المسخِّر؛ فاجعل تأمّلك في آياتِ الله في البحرِ والفلكِ سبيلًا لشكره وتوحيده وعبادته؛ فهو الذي سخّر لك البحرَ والسفن؛ فاشكره ووحّده."}},{"n":33,"reflection":{"text":"«إن يشأ يسكن الريح فيظللن رواكد على ظهره إن في ذلك لآيات لكل صبار شكور»: إن يشأ الله يسكّن الريحَ فتبقى السفنُ ثوابتَ على ظهرِ البحرِ لا تتحرّك، إنّ في ذلك لآياتٍ لكلِّ صبّارٍ شكور؛ ففي هذا بيانُ أنّ جريَ السفنِ بمشيئةِ الله، وأنّ الآياتِ ينتفع بها الصبّارُ الشكور؛ فكن صبّارًا شكورًا لتنتفع بآياتِ الله، فالصبرُ عند الشدّةِ والشكرُ عند النعمةِ من صفاتِ المنتفعين بالآيات.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الصبرِ والشكر، للانتفاعِ بآياتِ الله."},"action":{"text":"تأمّل قدرةَ الله في تسييرِ السفن: إن يشأ الله يسكّن الريحَ التي تسيّر السفن، فتبقى السفنُ رواكدَ ثوابتَ على ظهرِ البحرِ لا تتحرّك، فيهلك ركّابها أو يتضرّرون؛ إنّ في ذلك، من تسييرِ السفنِ وإمكانِ إيقافها، لآياتٍ ودلائلَ على قدرةِ الله ونعمته، لكلِّ صبّارٍ على البلاءِ شكورٍ على النعماء «إن يشأ يسكن الريح فيظللن رواكد على ظهره إن في ذلك لآيات لكل صبار شكور»؛ ففي هذا بيانُ أنّ جريَ السفنِ ووقوفها بمشيئةِ الله، وأنّ المنتفعين بالآياتِ هم أهلُ الصبرِ والشكر؛ فالصبّارُ الشكورُ ينتفع بآياتِ الله فيصبر في الشدّةِ ويشكر في النعمة؛ فكن صبّارًا شكورًا لتنتفع بآياتِ الله؛ فاجمع بين الصبرِ والشكر: اصبر عند الشدّةِ والبلاء، واشكر عند النعمةِ والرخاء؛ فالمؤمنُ أمره كلُّه خير: إن أصابته سرّاءُ شكر، وإن أصابته ضرّاءُ صبر؛ فالصبرُ والشكرُ جناحا الإيمان؛ فتحلَّ بهما لتنتفع بآياتِ الله؛ فمن جمع بين الصبرِ والشكرِ انتفع بآياتِ الله واستحقّ ثوابه؛ فاجعل الصبرَ والشكرَ خُلُقك في كلِّ حال؛ فبهما تكون من المنتفعين بآياتِ الله."}},{"n":34,"reflection":{"text":"«أو يوبقهن بما كسبوا ويعف عن كثير»: أو يُهلك السفنَ بذنوبِ أهلها، ويعفو عن كثيرٍ من ذنوبهم؛ ففي هذا أنّ الهلاكَ بالذنوبِ وسعةِ عفوِ الله؛ فاحذر الذنوبَ التي تجلب الهلاك، واعلم أنّ الله يعفو عن كثير، فتب من ذنوبك، واشكر عفوَ الله عمّا كسبت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الذنوبِ المهلِكة، وشكرُ عفوِ الله عن كثير."},"action":{"text":"تأمّل تمامَ الآية: أو يُوبق ويُهلك الله السفنَ ومن فيها بسببِ ما كسب أهلها من الذنوبِ والمعاصي؛ ويعفو الله عن كثيرٍ من ذنوبهم فلا يعاقبهم عليها «أو يوبقهن بما كسبوا ويعف عن كثير»؛ ففي هذا بيانُ أنّ الهلاكَ إنما يكون بالذنوب، وأنّ الله يعفو عن كثير؛ فلو شاء الله لأهلك أهلَ السفنِ بذنوبهم، لكنه يعفو عن كثير؛ فاحذر الذنوبَ والمعاصيَ التي تجلب الهلاكَ والعقوبات؛ فما نزل بلاءٌ إلا بذنب؛ فاجتنب أسبابَ الهلاكِ من المعاصي؛ واعلم أنّ الله يعفو عن كثيرٍ من ذنوبك برحمته وكرمه؛ فلولا عفوه لأهلك العبادَ بذنوبهم؛ ولو يؤاخذ الله الناسَ بما كسبوا ما ترك على ظهرها من دابّة؛ فاشكر عفوَ الله عمّا كسبت من الذنوب؛ وتب إليه ممّا اقترفت؛ فمن اجتنب الذنوبَ سلم من الهلاك، ومن أذنب ثم تاب عفا الله عنه؛ فاحذر الذنوب، وتب منها، واشكر عفوَ الله الواسع؛ فبعفوه ورحمته يُمهِل العباد، ويعفو عن كثيرٍ من ذنوبهم."}},{"n":35,"reflection":{"text":"«ويعلم الذين يجادلون في آياتنا ما لهم من محيص»، وليعلم الذين يجادلون في آياتِنا بالباطلِ أنه ما لهم من مهربٍ ولا ملجأٍ من عذابِ الله؛ ففي هذا وعيدُ المجادلين في الآياتِ بأنه لا مفرَّ لهم؛ فاحذر الجدالَ في آياتِ الله بالباطل، فإنه لا مهربَ لك من الله، فاقبل آياتِ الله ولا تجادل فيها، فالمجادلُ في الحقِّ لا محيصَ له من عذابِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجدالِ في آياتِ الله، وإدراكُ أنه لا مهربَ من عذابه."},"action":{"text":"تأمّل وعيدَ المجادلين في الآيات: أرسل الله الآياتِ والعِبَر ليعلم الذين يجادلون في آياتِ الله بالباطلِ لدفعها وردِّها، أنه ما لهم من محيصٍ ومهربٍ وملجأٍ من عذابِ الله إذا نزل بهم «ويعلم الذين يجادلون في آياتنا ما لهم من محيص»؛ ففي هذا وعيدُ المجادلين في آياتِ الله بأنه لا مفرَّ لهم ولا مهرب؛ فمن جادل في الحقِّ بالباطلِ ليردّه فلا محيصَ له من عذابِ الله؛ فاحذر الجدالَ في آياتِ الله بالباطلِ والشُّبَه؛ فإنه لا مهربَ لك من الله ولا ملجأ؛ فأينما فررت أدركك أمر الله؛ فلا محيصَ من الله إلا إليه؛ فاقبل آياتِ الله بالتصديقِ والإذعان؛ ولا تجادل فيها بالباطلِ لتردّها؛ فالجدالُ في الحقِّ بالباطلِ سببُ العذابِ الذي لا مهربَ منه؛ فلا تكن ممّن يجادل في آياتِ الله فيستحقّ العذابَ الذي لا محيصَ منه؛ بل كن ممّن يقبلها ويؤمن بها ويعمل بها؛ فمن قبل الحقَّ نجا، ومن جادل فيه بالباطلِ فلا محيصَ له من عذابِ الله."}},{"n":36,"reflection":{"text":"«فما أوتيتم من شيء فمتاع الحياة الدنيا وما عند الله خير وأبقى للذين آمنوا وعلى ربهم يتوكلون»: فما أُعطيتم من شيءٍ فهو متاعُ الحياةِ الدنيا الزائل، وما عند الله خيرٌ وأبقى للمؤمنين المتوكّلين على ربّهم؛ ففي هذا الموازنةُ بين متاعِ الدنيا وما عند الله؛ فآثر ما عند الله على متاعِ الدنيا، فما عند الله خيرٌ وأبقى، فاجعل الآخرةَ غايتك وتوكّل على ربّك، ولا تؤثر الفانيَ على الباقي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ ما عند الله على متاعِ الدنيا، والتوكّلُ على الرب."},"action":{"text":"تأمّل الموازنةَ بين الدنيا والآخرة: فما أوتيتم من شيءٍ من متاعِ الدنيا، مالٍ أو جاهٍ أو ولدٍ أو زينة، فهو متاعُ الحياةِ الدنيا الزائلُ الفاني؛ وما عند الله من الثوابِ والنعيمِ خيرٌ وأبقى للذين آمنوا وعلى ربّهم يتوكّلون «فما أوتيتم من شيء فمتاع الحياة الدنيا وما عند الله خير وأبقى للذين آمنوا وعلى ربهم يتوكلون»؛ ففي هذا الموازنةُ بين متاعِ الدنيا الزائلِ وما عند الله الباقي؛ فمتاعُ الدنيا قليلٌ زائل، وما عند الله خيرٌ وأبقى؛ فآثر ما عند الله على متاعِ الدنيا؛ فما عند الله خيرٌ في نوعه، وأبقى في دوامه؛ بل تؤثرون الحياةَ الدنيا والآخرةُ خيرٌ وأبقى؛ فاجعل الآخرةَ غايتك، وما عند الله مطلبك؛ ولا تؤثر الفانيَ على الباقي؛ فالعاقلُ يؤثر ما يبقى على ما يفنى؛ وتوكّل على ربّك في جميعِ أمورك؛ فالتوكّلُ من صفاتِ المؤمنين الفائزين بما عند الله؛ فمن آثر ما عند الله وتوكّل على ربّه فاز بالخيرِ الباقي؛ ومن آثر متاعَ الدنيا خسر الآخرة؛ فاجعل همّك ما عند الله؛ واعمل للباقي، وتوكّل على ربّك؛ فما عند الله خيرٌ وأبقى."}},{"n":37,"reflection":{"text":"«والذين يجتنبون كبائر الإثم والفواحش وإذا ما غضبوا هم يغفرون»، والذين يجتنبون كبائرَ الذنوبِ والفواحشَ، وإذا غضبوا يعفون ويصفحون؛ ففي هذا وصفُ المؤمنين باجتنابِ الكبائرِ والعفوِ عند الغضب؛ فاجتنب كبائرَ الإثمِ والفواحش، واعفُ عند الغضب، فالعفوُ عند القدرةِ من صفاتِ المؤمنين، فتحلَّ باجتنابِ الكبائرِ والعفوِ عند الغضب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الكبائرِ والفواحش، والعفوُ عند الغضب."},"action":{"text":"تأمّل صفاتِ المؤمنين الذين لهم ما عند الله: والذين يجتنبون كبائرَ الإثمِ، عظائمَ الذنوب، والفواحشَ، ما اشتدّ قبحه من الزنا ونحوه؛ وإذا ما غضبوا هم يغفرون ويعفون ويصفحون عمّن أساء إليهم، لا ينتقمون لأنفسهم «والذين يجتنبون كبائر الإثم والفواحش وإذا ما غضبوا هم يغفرون»؛ ففي هذا وصفُ المؤمنين باجتنابِ الكبائرِ والفواحش، وبالعفوِ والحلمِ عند الغضب؛ فاجتنب كبائرَ الإثمِ والفواحش؛ فإن تجتنبوا كبائرَ ما تُنهَون عنه نكفّر عنكم سيّئاتكم؛ فاجتنابُ الكبائرِ سببٌ لتكفيرِ الصغائر؛ واعفُ عند الغضبِ عمّن أساء إليك؛ فالعفوُ عند القدرةِ والحلمُ عند الغضبِ من صفاتِ المؤمنين وأخلاقِ الكرام؛ والكاظمين الغيظَ والعافين عن الناسِ والله يحبّ المحسنين؛ فتحلَّ باجتنابِ الكبائرِ والفواحش، وبالعفوِ والصفحِ عند الغضب؛ فراقب نفسك عند الغضب: هل تنتقم أم تعفو؟ فجاهدها على العفوِ والحلم؛ فمن اجتنب الكبائرَ وعفا عند الغضبِ فقد اتّصف بصفاتِ المؤمنين؛ فاجعل هذين الخُلُقين لك: اجتنابَ عظائمِ الذنوب، والعفوَ عند الغضب."}},{"n":38,"reflection":{"text":"«والذين استجابوا لربهم وأقاموا الصلاة وأمرهم شورى بينهم ومما رزقناهم ينفقون»، والذين استجابوا لربّهم وأقاموا الصلاةَ وأمرهم شورى بينهم ومما رزقناهم ينفقون؛ ففي هذا وصفُ المؤمنين بالاستجابةِ والصلاةِ والشورى والإنفاق؛ فاستجب لربّك، وأقم الصلاة، وشاور في أمورك، وأنفق مما رزقك الله، فالشورى وإقامةُ الصلاةِ والإنفاقُ من صفاتِ المؤمنين، فتحلَّ بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستجابةُ لله وإقامةُ الصلاةِ والشورى والإنفاق."},"action":{"text":"تأمّل صفاتِ المؤمنين الجامعة: والذين استجابوا لربّهم فأطاعوه واتّبعوا أمره؛ وأقاموا الصلاةَ بحدودها وأركانها وخشوعها؛ وأمرهم شورى بينهم، يتشاورون في أمورهم العامّةِ فلا ينفرد أحدهم برأيه؛ ومما رزقناهم من الأموالِ ينفقون في وجوهِ الخير «والذين استجابوا لربهم وأقاموا الصلاة وأمرهم شورى بينهم ومما رزقناهم ينفقون»؛ ففي هذا وصفُ المؤمنين بأربعِ خصال: الاستجابةِ لله، وإقامةِ الصلاة، والشورى، والإنفاق؛ فاستجب لربّك بطاعته واتّباعِ أمره؛ وأقم الصلاةَ بأركانها وخشوعها ومواقيتها؛ وشاور في أمورك العامّةِ والخاصّةِ أهلَ الرأيِ والعلم؛ فالشورى من هدي الإسلام؛ وشاورهم في الأمر؛ فما خاب من استشار؛ ولا ينفرد برأيه إلا ناقص؛ وأنفق مما رزقك الله في وجوهِ الخيرِ والبرّ؛ فالإنفاقُ من صفاتِ المؤمنين المتّقين؛ فتحلَّ بهذه الخصالِ الأربع: الاستجابةِ لله، وإقامةِ الصلاة، والتشاورِ في الأمور، والإنفاقِ في الخير؛ فمن اتّصف بها كان من المؤمنين الذين لهم ما عند الله؛ فاجعلها منهجك في حياتك؛ فبها تكمل عبوديتك، وتنتظم أمورك، ويصلح مجتمعك."}},{"n":39,"reflection":{"text":"«والذين إذا أصابهم البغي هم ينتصرون»، والذين إذا أصابهم الظلمُ والبغيُ ينتصرون لأنفسهم بالحقّ؛ ففي هذا جوازُ الانتصارِ من الظالمِ بالحق؛ فانتصر من الظلمِ بالحقِّ والعدل، فليس الانتصارُ من الظالمِ مذمومًا، بل هو من العزّةِ والكرامة، فادفع الظلمَ عن نفسك بالحقِّ دون تعدٍّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانتصارُ من الظلمِ بالحقّ، ودفعُ البغيِ دون تعدٍّ."},"action":{"text":"تأمّل وصفَ المؤمنين بالعزّة: والذين إذا أصابهم البغيُ والظلمُ والعدوانُ هم ينتصرون لأنفسهم وللحقِّ من الظالمين، بلا ذلٍّ ولا استكانةٍ للباطل «والذين إذا أصابهم البغي هم ينتصرون»؛ ففي هذا بيانُ جوازِ الانتصارِ من الظالمِ بالحق، وأنّ ذلك من صفاتِ المؤمنين الأعزّة؛ فالمؤمنُ يعفو حيث يكون العفوُ خيرًا، وينتصر حيث يكون الانتصارُ حقًّا ومصلحة؛ فلا يكون ذليلًا مهانًا يُطمَع فيه؛ فانتصر من الظلمِ بالحقِّ والعدلِ إذا كان ذلك خيرًا؛ فليس الانتصارُ من الظالمِ مذمومًا؛ بل هو من العزّةِ والكرامةِ وحفظِ الحقوق؛ فادفع الظلمَ عن نفسك وعن غيرك بالحقِّ دون تعدٍّ ولا ظلم؛ فالمؤمنُ عزيزٌ لا يُذَلّ، قويٌّ لا يُهان؛ ولكن انتصاره بالحقِّ والعدل، لا بالبغيِ والظلم؛ فوازن بين العفوِ والانتصار: فحيث كان العفوُ أصلحَ فاعفُ، وحيث كان الانتصارُ أحقَّ فانتصر بالعدل؛ فالمؤمنُ يجمع بين الرحمةِ والعزّة، والعفوِ والانتصار، بحسبِ المصلحةِ والحق؛ فاجعل انتصارك من الظالمِ بالحقِّ والعدل، دون تعدٍّ ولا ظلم."}}]},{"title":"جزاءُ السيّئةِ والعفو، والانتصارُ من الظلم، وفضلُ الصبر","range":[40,43],"theme":"أنّ جزاءَ السيّئةِ مثلها ومن عفا وأصلح فأجره على الله وأنه لا يحبّ الظالمين، وأنّ من انتصر بعد ظلمه فلا سبيلَ عليه وإنما السبيلُ على الظالمين الباغين ولهم عذابٌ أليم، وأنّ من صبر وغفر فذلك من عزمِ الأمور","verses":[{"n":40,"reflection":{"text":"«وجزاء سيئة سيئة مثلها فمن عفا وأصلح فأجره على الله إنه لا يحب الظالمين»، وجزاءُ السيّئةِ عقوبةٌ مثلها بلا زيادة، فمن عفا عمّن ظلمه وأصلح فأجره على الله، إنه لا يحبّ الظالمين؛ ففي هذا تقريرُ العدلِ في القصاصِ وفضلِ العفو؛ فاعدل في مجازاةِ المسيء، والأفضلُ أن تعفوَ وتُصلح، فأجرُ العافي على الله، فاعفُ لتنال أجرَ الله، ولا تظلم فتُبغَض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العدلُ في مجازاةِ المسيء، وفضلُ العفوِ والإصلاح."},"action":{"text":"تأمّل تقريرَ العدلِ وفضلِ العفو: وجزاءُ السيّئةِ عقوبةٌ مثلها لا تزيد عليها، عدلًا؛ فمن عفا عمّن ظلمه وأصلح بينه وبين خصمه فأجره على الله يعظّمه ويضاعفه؛ إنه لا يحبّ الظالمين المعتدين المتجاوزين في العقوبة «وجزاء سيئة سيئة مثلها فمن عفا وأصلح فأجره على الله إنه لا يحب الظالمين»؛ ففي هذا تقريرُ العدلِ في القصاصِ والمجازاة، وبيانُ فضلِ العفوِ والإصلاح؛ فالعدلُ أن تجازيَ المسيءَ بمثلِ إساءته لا أكثر؛ فمن اعتدى عليكم فاعتدوا عليه بمثلِ ما اعتدى عليكم؛ والأفضلُ والأكملُ أن تعفوَ عمّن ظلمك وتُصلح؛ فأجرُ العافي المصلحِ على الله؛ وأجرُ الله أعظمُ وأبقى؛ فاعدل في مجازاةِ المسيءِ إن جازيت؛ والأفضلُ أن تعفوَ وتُصلح لتنال أجرَ الله؛ وأن تعفوا أقربُ للتقوى؛ فالعفوُ عند القدرةِ من كمالِ الأخلاق؛ فاعفُ عمّن ظلمك، وأصلح، لتنال أجرَ الله المضاعف؛ واحذر الظلمَ والتعدّي في العقوبة؛ فإنّ الله لا يحبّ الظالمين؛ فمن جازى بالعدلِ فقد أنصف، ومن عفا وأصلح فقد أحسن ونال أجرَ الله، ومن ظلم وتعدّى فقد استحقّ بغضَ الله."}},{"n":41,"reflection":{"text":"«ولمن انتصر بعد ظلمه فأولئك ما عليهم من سبيل»، ولمن انتصر لنفسه بالحقِّ بعد ظلمه، فأولئك ما عليهم من لومٍ ولا عقوبة؛ ففي هذا بيانُ أنّ المنتصرَ بالحقِّ لا لومَ عليه؛ فاعلم أنّ من انتصر من ظالمِه بالحقِّ فلا حرجَ عليه، فادفع الظلمَ عنك بالحقّ، فالانتصارُ بالحقِّ من الظالمِ لا لومَ فيه ولا إثم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ المنتصرَ بالحقِّ من ظالمِه لا لومَ عليه."},"action":{"text":"تأمّل بيانَ حقِّ المظلوم: ولمن انتصر لنفسه بالحقِّ بعد أن ظُلِم، فأخذ حقّه ممّن ظلمه، فأولئك ما عليهم من سبيلٍ، أي لا لومَ عليهم ولا عقوبةَ ولا حرج «ولمن انتصر بعد ظلمه فأولئك ما عليهم من سبيل»؛ ففي هذا بيانُ أنّ المظلومَ الذي ينتصر لنفسه بالحقِّ لا لومَ عليه ولا حرج؛ فمن أخذ حقّه من ظالمِه بالعدلِ والحقِّ فلا إثمَ عليه؛ فاعلم أنّ من انتصر من ظالمِه بالحقِّ فلا حرجَ عليه ولا لوم؛ فحقُّ المظلومِ أن يأخذ حقّه؛ فادفع الظلمَ عنك، وخذ حقّك ممّن ظلمك، بالحقِّ والعدلِ دون تعدٍّ؛ فالانتصارُ بالحقِّ من الظالمِ لا لومَ فيه ولا إثم؛ وإن كان العفوُ أفضل؛ فالمؤمنُ مخيّرٌ بين أخذِ حقّه بالعدلِ أو العفوِ لوجهِ الله؛ فإن أخذ حقّه فلا لومَ عليه، وإن عفا فأجره على الله؛ فلا تظنّ أنّ أخذَ الحقِّ من الظالمِ مذموم؛ بل هو حقٌّ مشروع؛ فاطلب حقّك بالعدل، أو اعفُ لوجهِ الله؛ فكلاهما جائز، والعفوُ أفضل؛ فمن انتصر بالحقِّ فلا سبيلَ عليه، ومن عفا فله الأجرُ العظيم."}},{"n":42,"reflection":{"text":"«إنما السبيل على الذين يظلمون الناس ويبغون في الأرض بغير الحق أولئك لهم عذاب أليم»: إنما اللومُ والعقوبةُ على الذين يظلمون الناسَ ويبغون في الأرضِ بغيرِ حق، أولئك لهم عذابٌ أليم؛ ففي هذا بيانُ أنّ اللومَ على الظالمين الباغين؛ فاحذر ظلمَ الناسِ والبغيَ في الأرض، فإنه سببُ اللومِ والعذاب، فاجتنب الظلمَ والعدوان، فالظالمون الباغون لهم عذابٌ أليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من ظلمِ الناسِ والبغيِ في الأرض، فعاقبتُه العذابُ الأليم."},"action":{"text":"تأمّل بيانَ من عليه اللومُ والعقوبة: إنما السبيلُ، اللومُ والعقوبةُ والمؤاخذة، على الذين يظلمون الناسَ ويعتدون على حقوقهم وأنفسهم، ويبغون ويفسدون في الأرضِ بغيرِ الحق؛ أولئك الظالمون الباغون لهم عذابٌ أليمٌ في الآخرة «إنما السبيل على الذين يظلمون الناس ويبغون في الأرض بغير الحق أولئك لهم عذاب أليم»؛ ففي هذا بيانُ أنّ اللومَ والعقوبةَ إنما هما على الظالمين الباغين المفسدين؛ فاحذر ظلمَ الناسِ والاعتداءَ على حقوقهم وأنفسهم وأموالهم وأعراضهم؛ واحذر البغيَ والفسادَ في الأرضِ بغيرِ الحق؛ فإنّ ذلك سببُ اللومِ والعقوبةِ والعذابِ الأليم؛ فالظلمُ ظلماتٌ يومَ القيامة؛ واتّق دعوةَ المظلومِ فإنها تُرفَع إلى الله؛ فاجتنب الظلمَ والبغيَ والعدوانَ بجميعِ صوره؛ ولا تظلم أحدًا في نفسٍ أو مالٍ أو عرض؛ ولا تبغِ في الأرضِ ولا تفسد فيها؛ فالظالمون الباغون لهم عذابٌ أليم؛ فمن اجتنب الظلمَ والبغيَ سلم ونجا، ومن ظلم وبغى استحقّ العذابَ الأليم؛ فاجعل نفسك من أهلِ العدلِ والإحسان، لا من أهلِ الظلمِ والبغي."}},{"n":43,"reflection":{"text":"«ولمن صبر وغفر إن ذلك لمن عزم الأمور»، ولمن صبر على الأذى وغفر لمن ظلمه، إنّ ذلك لمن معالي الأمورِ التي يُعزَم عليها؛ ففي هذا بيانُ فضلِ الصبرِ والعفو؛ فاصبر على الأذى واعفُ عمّن ظلمك، فالصبرُ والعفوُ من عزائمِ الأمورِ ومعاليها، فتحلَّ بالصبرِ والعفو، فهما من أشرفِ الأخلاقِ وأعظمِ العزائم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى والعفوُ عمّن ظلم، فهما من عزائمِ الأمور."},"action":{"text":"تأمّل فضلَ الصبرِ والعفو: ولمن صبر على الأذى والظلمِ وغفر وعفا عمّن ظلمه، إنّ ذلك الصبرَ والعفوَ لمن عزمِ الأمورِ ومعاليها التي يُعزَم عليها ويُرغَب فيها، ويحتاج إلى عزيمةٍ قويّةٍ ونفسٍ كبيرة «ولمن صبر وغفر إن ذلك لمن عزم الأمور»؛ ففي هذا بيانُ فضلِ الصبرِ على الأذى والعفوِ عن الظالم، وأنهما من معالي الأخلاق؛ فالصبرُ والعفوُ يحتاجان إلى عزيمةٍ وقوّةِ نفس؛ ولا يقدر عليهما إلا أصحابُ الهممِ العالية؛ فاصبر على الأذى الذي يصيبك من الناس؛ واعفُ عمّن ظلمك وأساء إليك؛ فالصبرُ والعفوُ من عزائمِ الأمورِ ومعاليها؛ وليس الشديدُ بالصرعة، إنما الشديدُ الذي يملك نفسه عند الغضب؛ فما زاد الله عبدًا بعفوٍ إلا عزًّا؛ فتحلَّ بالصبرِ على الأذى والعفوِ عن الظالم؛ فهما من أشرفِ الأخلاقِ وأعظمِ العزائم؛ فمن صبر وعفا نال أعلى الدرجاتِ وأجرَ الله العظيم؛ فاجعل الصبرَ والعفوَ خُلُقك؛ فبهما تعلو نفسك، وتنال محبّةَ الله، وترتفع درجتك؛ فالصبرُ والعفوُ من عزمِ الأمورِ التي يتنافس فيها المتنافسون."}}]},{"title":"عاقبةُ الظالمين وذلُّهم، وحرمانُهم من النصرة، والأمرُ بالاستجابة، والبلاغ","range":[44,48],"theme":"أنّ من يضلله الله فلا وليَّ له وتمنّي الظالمين الرجعةَ عند العذاب وعرضُهم على النارِ خاشعين وأنّ الخاسرين من خسروا أنفسهم وأهليهم، وأنهم لا أولياءَ لهم ينصرونهم، والأمرُ بالاستجابةِ لله قبل يومٍ لا مردَّ له، وأنّ على النبيِّ البلاغَ لا الحفظَ وذمُّ كفرانِ الإنسانِ عند الشدّةِ وفرحِه بالنعمة","verses":[{"n":44,"reflection":{"text":"«ومن يضلل الله فما له من ولي من بعده وترى الظالمين لما رأوا العذاب يقولون هل إلى مرد من سبيل»، ومن يضلله الله فما له من وليٍّ يهديه، وترى الظالمين لمّا رأوا العذاب يقولون: هل إلى رجوعٍ إلى الدنيا من سبيل؟ ففي هذا بيانُ حرمانِ الضالِّ من الولاية وندمِ الظالمين؛ فاطلب الهدايةَ من الله واعتصم به، ولا تؤخّر التوبةَ حتى ترى العذابَ فتتمنّى الرجعةَ حيث لا تنفع، فبادر بالتوبةِ الآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله، والمبادرةُ بالتوبةِ قبل رؤيةِ العذاب."},"action":{"text":"تأمّل حالَ الظالمين عند العذاب: ومن يضلله الله بعدله فما له من وليٍّ يتولّاه ويهديه من بعدِ إضلالِ الله له؛ وترى الظالمين يومَ القيامةِ لمّا رأوا العذابَ وعاينوه يقولون متحسّرين: هل إلى مردٍّ ورجوعٍ إلى الدنيا من سبيلٍ لنعمل صالحًا؟ ولاتَ حينَ رجوع «ومن يضلل الله فما له من ولي من بعده وترى الظالمين لما رأوا العذاب يقولون هل إلى مرد من سبيل»؛ ففي هذا بيانُ حرمانِ الضالِّ من الولايةِ والهداية، وندمِ الظالمين عند رؤيةِ العذابِ وتمنّيهم الرجعة؛ فاطلب الهدايةَ من الله واعتصم به؛ فمن هداه الله فلا مُضِلَّ له، ومن أضلّه فلا هاديَ له؛ فاسأل الله الهدايةَ والثبات؛ ولا تؤخّر التوبةَ والعملَ الصالحَ حتى ترى العذابَ فتتمنّى الرجعةَ حيث لا تنفع؛ فإنّ الظالمين يتمنّون الرجعةَ عند رؤيةِ العذابِ فلا يُجابون؛ ولو ردّوا لعادوا لما نُهوا عنه؛ فبادر بالتوبةِ والعملِ الصالحِ الآن، في زمنِ المهلة؛ فمن تاب وعمل صالحًا في الدنيا نجا، ومن أخّر حتى رأى العذابَ ندم وتمنّى الرجعةَ فلا تنفعه؛ فلا تسوّف بالتوبة؛ واغتنم مهلةَ حياتك بالعملِ الصالحِ قبل فواتِ الأوان."}},{"n":45,"reflection":{"text":"«وتراهم يعرضون عليها خاشعين من الذل ينظرون من طرف خفي وقال الذين آمنوا إن الخاسرين الذين خسروا أنفسهم وأهليهم يوم القيامة ألا إن الظالمين في عذاب مقيم»، وتراهم يُعرَضون على النارِ خاشعين من الذلِّ ينظرون نظرًا خفيًّا، وقال المؤمنون: إنّ الخاسرين الذين خسروا أنفسهم وأهليهم يومَ القيامة، ألا إنّ الظالمين في عذابٍ مقيم؛ ففي هذا مشهدُ ذلِّ الظالمين وحقيقةُ الخسران؛ فاعمل لنجاةِ نفسك وأهلك من الخسرانِ يومَ القيامة، فالخاسرُ من خسر نفسه، فاعمل لتنجو من العذابِ المقيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنجاةِ النفسِ والأهلِ من الخسرانِ والعذابِ المقيم."},"action":{"text":"تأمّل مشهدَ ذلِّ الظالمين وحقيقةَ الخسران: وترى الظالمين يومَ القيامةِ يُعرَضون على النارِ خاشعين ذليلين من هولِ الموقفِ والذلّ، ينظرون إلى النارِ نظرًا خفيًّا خائفًا من شدّةِ الرعب؛ وقال المؤمنون: إنّ الخاسرين حقًّا هم الذين خسروا أنفسهم وأهليهم يومَ القيامة، بأن أوردوها النارَ وحُرِموا نعيمَ الجنّة؛ ألا إنّ الظالمين في عذابٍ دائمٍ مقيمٍ لا ينقطع «وتراهم يعرضون عليها خاشعين من الذل... إن الخاسرين الذين خسروا أنفسهم وأهليهم يوم القيامة ألا إن الظالمين في عذاب مقيم»؛ ففي هذا مشهدُ ذلِّ الظالمين عند العذاب، وبيانُ حقيقةِ الخسرانِ الأكبر؛ فالخاسرُ حقًّا من خسر نفسه وأهله يومَ القيامةِ بدخولِ النار؛ فاعمل لنجاةِ نفسك وأهلك من هذا الخسرانِ والعذابِ المقيم؛ قوا أنفسكم وأهليكم نارًا؛ فاجتهد في هدايةِ نفسك أولًا بالإيمانِ والتوحيدِ والطاعة؛ ثم في هدايةِ أهلك بالتعليمِ والنصحِ والقدوة؛ فالخسارةُ الحقيقيةُ خسارةُ النفسِ والأهلِ في الآخرة، لا خسارةُ الدنيا؛ فاعمل للربحِ الحقيقي: نجاةِ نفسك وأهلك؛ واحذر الظلمَ الذي عاقبتُه العذابُ المقيم؛ فمن آمن وعمل صالحًا ونجّى أهله فاز، ومن ظلم وأضاع نفسه وأهله خسر خسرانًا مبينًا؛ فبادر بالعملِ لنجاتك ونجاةِ أهلك."}},{"n":46,"reflection":{"text":"«وما كان لهم من أولياء ينصرونهم من دون الله ومن يضلل الله فما له من سبيل»، وما كان للظالمين من أولياءَ ينصرونهم من دونِ الله، ومن يضلله الله فما له من سبيلٍ إلى الهداية؛ ففي هذا بيانُ حرمانِ الظالمين من النصرةِ والهداية؛ فاطلب ولايةَ الله ونصرته وهدايته، ولا تعتمد على غيره، فمن حُرِم هدايةَ الله فلا سبيلَ له، فالجأ إلى الله واطلب هدايته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ولايةِ الله ونصرته وهدايته، وعدمُ الاعتمادِ على غيره."},"action":{"text":"تأمّل حرمانَ الظالمين من النصرةِ والهداية: وما كان للظالمين من أولياءَ ينصرونهم ويدفعون عنهم عذابَ الله من دونِ الله؛ فلا ناصرَ لهم ولا وليّ؛ ومن يضلله الله بعدله فما له من سبيلٍ إلى الهدايةِ والنجاة «وما كان لهم من أولياء ينصرونهم من دون الله ومن يضلل الله فما له من سبيل»؛ ففي هذا بيانُ حرمانِ الظالمين من النصرةِ والهدايةِ والولاية؛ فالظالمون لا وليَّ لهم ينصرهم، ولا سبيلَ لهم إلى الهداية بعد إضلالِ الله لهم؛ فاطلب ولايةَ الله ونصرته وهدايته بالإيمانِ والطاعةِ والإنابة؛ ولا تعتمد على غيرِ الله؛ فمن اعتمد على غيرِ الله خُذِل؛ فالله وليُّ المؤمنين وناصرهم وهاديهم؛ فمن كان الله وليّه ونصيره وهاديه فاز؛ ومن حُرِم ولايةَ الله ونصرته وهدايته فلا سبيلَ له إلى النجاة؛ فالجأ إلى الله، واطلب هدايته وولايته ونصرته؛ واعتصم به؛ فمن اعتصم بالله هداه ونصره وتولّاه؛ فاجعل توكّلك ورجاءك وولاءك لله وحده؛ فلا ناصرَ ولا هاديَ ولا وليَّ سواه؛ فبولايةِ الله وهدايته ونصرته تُنال النجاةُ والفوز."}},{"n":47,"reflection":{"text":"«استجيبوا لربكم من قبل أن يأتي يوم لا مرد له من الله ما لكم من ملجإ يومئذ وما لكم من نكير»: استجيبوا لربّكم من قبل أن يأتيَ يومٌ لا يُردّ من الله، ما لكم يومئذٍ من ملجأٍ تلجؤون إليه ولا من إنكارٍ لذنوبكم؛ ففي هذا الأمرُ بالاستجابةِ قبل يومِ القيامة؛ فاستجب لربّك الآن بالإيمانِ والطاعةِ قبل أن يأتيَ يومٌ لا مفرَّ منه، فبادر بالطاعةِ قبل فواتِ الأوان، فيومَ القيامةِ لا ملجأ ولا إنكار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالاستجابةِ لله قبل يومٍ لا مردَّ له ولا ملجأ."},"action":{"text":"تأمّل الأمرَ العظيمَ بالاستجابة: استجيبوا لربّكم بالإيمانِ والطاعةِ والامتثالِ من قبل أن يأتيَ يومُ القيامةِ الذي لا مردَّ له ولا دفعَ من الله؛ ما لكم يومئذٍ من ملجأٍ تلجؤون إليه من العذاب، وما لكم من نكيرٍ، أي لا تقدرون على إنكارِ ذنوبكم، فقد شهدت عليكم جوارحكم «استجيبوا لربكم من قبل أن يأتي يوم لا مرد له من الله ما لكم من ملجإ يومئذ وما لكم من نكير»؛ ففي هذا الأمرُ بالمبادرةِ إلى الاستجابةِ لله قبل يومِ القيامة؛ فاستجب لربّك الآن بالإيمانِ والتوحيدِ والطاعةِ والتوبة؛ من قبل أن يأتيَ يومٌ لا مردَّ له ولا مفرَّ منه؛ فيومئذٍ لا ملجأ ولا مهرب؛ يقول الإنسانُ يومئذٍ أين المفرّ؟ كلا لا وزر، إلى ربك يومئذٍ المستقر؛ ولا تقدر على إنكارِ ذنوبك؛ فقد أُحصِيت عليك وشهدت بها جوارحك؛ فبادر بالاستجابةِ لله والعملِ الصالحِ قبل فواتِ الأوان؛ فمن استجاب لله في الدنيا نجا، ومن أعرض حتى جاء ذلك اليومُ لم ينفعه شيء؛ فلا تسوّف بالاستجابةِ والتوبة؛ واغتنم مهلةَ حياتك؛ فاستجب لله الآن، وبادر بالطاعةِ والتوبةِ قبل أن يأتيَ يومٌ لا مردَّ له ولا ملجأَ فيه."}},{"n":48,"reflection":{"text":"«فإن أعرضوا فما أرسلناك عليهم حفيظا إن عليك إلا البلاغ وإنا إذا أذقنا الإنسان منا رحمة فرح بها وإن تصبهم سيئة بما قدمت أيديهم فإن الإنسان كفور»: فإن أعرضوا فما أرسلناك حفيظًا عليهم، ما عليك إلا البلاغ، وإنا إذا أذقنا الإنسانَ رحمةً فرح بها، وإن تصبهم سيّئةٌ بما قدّموا فإنّ الإنسانَ كفور؛ ففي هذا تخفيفُ عبءِ الهدايةِ عن النبيِّ وذمُّ كفرانِ الإنسان؛ فابلّغ الحقَّ ولا تحزن على المعرضين، واحذر كفرانَ النعمةِ والجزعَ عند الشدّة، فاشكر في الرخاءِ واصبر في الشدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تبليغُ الحقِّ دون حزن، والشكرُ في الرخاءِ والصبرُ في الشدّة."},"action":{"text":"تأمّل تخفيفَ العبءِ عن النبيِّ وذمَّ الإنسان: فإن أعرض هؤلاء عن الحقِّ بعد البلاغ، فما أرسلناك يا محمدُ حفيظًا عليهم توكَل بحفظهم وهدايتهم؛ ما عليك إلا البلاغُ المبين، وعلى الله الحساب؛ وإنا إذا أذقنا الإنسانَ منّا رحمةً، نعمةً وعافيةً، فرح بها فرحَ بطرٍ وأشر؛ وإن تصبهم سيّئةٌ، شدّةٌ أو بلاءٌ، بسببِ ما قدّمت أيديهم من الذنوب، فإنّ الإنسانَ كفورٌ جحودٌ لنعمِ الله «فإن أعرضوا فما أرسلناك عليهم حفيظا إن عليك إلا البلاغ... فإن الإنسان كفور»؛ ففي هذا تخفيفُ عبءِ الهدايةِ عن النبيّ، وبيانُ أنّ عليه البلاغَ فقط، وذمُّ كفرانِ الإنسانِ وجزعِه؛ فابلّغ الحقَّ لمن حولك؛ ثم لا تحزن على من أعرض؛ فليس عليك هداهم، إنما عليك البلاغ؛ ما على الرسولِ إلا البلاغ؛ واحذر أنت كفرانَ النعمةِ والفرحَ بها بطرًا، والجزعَ عند الشدّةِ والكفرانَ عندها؛ بل اشكر الله في الرخاءِ والنعمة، واصبر في الشدّةِ والبلاء؛ فالمؤمنُ أمره كلُّه خير: إن أصابته سرّاءُ شكر، وإن أصابته ضرّاءُ صبر؛ فلا تكن من الإنسانِ الكفورِ الذي يفرح بطرًا ويكفر عند الشدّة؛ بل كن شاكرًا صابرًا؛ فبالشكرِ في الرخاءِ والصبرِ في الشدّةِ تكمل عبوديتك."}}]},{"title":"ملكُ الله وهبةُ الأولاد، وكيفيةُ الوحي، وختامُ صراطِ الله ومصيرِ الأمور","range":[49,53],"theme":"أنّ لله ملكَ السماواتِ والأرضِ يهب لمن يشاء إناثًا وذكورًا ويجعل من يشاء عقيمًا بعلمه وقدرته، وأنّ الله لا يكلّم البشرَ إلا وحيًا أو من وراءِ حجابٍ أو بإرسالِ رسول، وأنّ القرآنَ روحٌ ونورٌ أوحاه الله إلى نبيّه ليهدي به إلى صراطِ الله المستقيم الذي له ما في السماواتِ والأرضِ وإليه تصير الأمور","verses":[{"n":49,"reflection":{"text":"«لله ملك السماوات والأرض يخلق ما يشاء يهب لمن يشاء إناثا ويهب لمن يشاء الذكور»: لله ملكُ السماواتِ والأرض، يخلق ما يشاء، يهب لمن يشاء إناثًا ويهب لمن يشاء الذكور؛ ففي هذا تقريرُ ملكِ الله وتصرّفِه في خلقه؛ فسلّم لله في تصرّفِه وقسمته، فمن وهبه الله إناثًا أو ذكورًا فبحكمته، فارضَ بقسمةِ الله في الولدِ وغيره، ولا تعترض على تدبيرِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في قسمتِه وتصرّفِه، والرضا بتدبيره في الولد."},"action":{"text":"تأمّل تصرّفَ الله في ملكه: لله وحده ملكُ السماواتِ والأرض؛ يخلق ما يشاء بحكمته؛ يهب لمن يشاء إناثًا فقط، ويهب لمن يشاء الذكورَ فقط «لله ملك السماوات والأرض يخلق ما يشاء يهب لمن يشاء إناثا ويهب لمن يشاء الذكور»؛ ففي هذا تقريرُ ملكِ الله الشامل، وتصرّفِه في خلقه بحكمته؛ فهو يخلق ما يشاء ويهب ما يشاء بحكمته وعلمه؛ فسلّم لله في تصرّفِه وقسمته؛ فما وهبك الله من ولدٍ، ذكرًا أو أنثى، فبحكمته ولطفه؛ فارضَ بقسمةِ الله في الولدِ وفي كلِّ شيء؛ ولا تكره ما وهبك الله من الإناث؛ فقد كان أهلُ الجاهليةِ يكرهون البنات؛ فذمّهم الله؛ فالبناتُ والبنون هبةٌ من الله ونعمة؛ فاشكر الله على ما وهبك؛ ولا تعترض على تدبيرِ الله وقسمته؛ فهو أعلمُ بما يصلحك؛ فمن سلّم لله في قسمته وتصرّفِه رضي واطمأنّ؛ ومن اعترض على تدبيرِ الله شقي وتعب؛ فاجعل تسليمك لله في تصرّفِه وقسمته؛ وارضَ بما وهبك؛ واشكره على نعمه؛ فالملكُ كلُّه لله، يتصرّف فيه بحكمته."}},{"n":50,"reflection":{"text":"«أو يزوجهم ذكرانا وإناثا ويجعل من يشاء عقيما إنه عليم قدير»: أو يجعل لهم ذكورًا وإناثًا معًا، ويجعل من يشاء عقيمًا لا ولدَ له، إنه عليمٌ قدير؛ ففي هذا تمامُ تصرّفِ الله في الولد؛ فسلّم لله في قسمته، فمن رزقه الله ولدًا أو حرمه فبعلمه وقدرته وحكمته، فارضَ بقضاءِ الله في الولد، فهو العليمُ بما يصلحك القادرُ على كلِّ شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في قضائه بالولدِ والعقم، والرضا بحكمته."},"action":{"text":"تأمّل تمامَ تصرّفِ الله: أو يزوّجهم ويجمع لهم ذكرانًا وإناثًا معًا؛ ويجعل من يشاء عقيمًا لا يولد له؛ إنه عليمٌ بما يصلح عباده، قديرٌ على كلِّ ما يشاء «أو يزوجهم ذكرانا وإناثا ويجعل من يشاء عقيما إنه عليم قدير»؛ ففي هذا تمامُ بيانِ تصرّفِ الله في الولد: فمنهم من يهبه ذكورًا، ومنهم إناثًا، ومنهم الصنفين، ومنهم من يجعله عقيمًا؛ كلُّ ذلك بعلمه وقدرته وحكمته؛ فسلّم لله في قسمته وقضائه؛ فمن رزقه الله ولدًا فليشكر، ومن حرمه فليصبر ويرضَ؛ فكلاهما بحكمةٍ من الله العليمِ القدير؛ فارضَ بقضاءِ الله في الولد؛ فلا تجزع إن حُرِمت الولد، ولا تبطر إن رُزِقته؛ فالله أعلمُ بما يصلحك؛ فكم من محرومٍ من الولدِ كان ذلك خيرًا له، وكم من مرزوقٍ به كان فتنةً عليه؛ فسلّم لله العليمِ القدير؛ وارضَ بقضائه وقدره؛ واعلم أنه يقدّر لك ما هو خيرٌ لك بعلمه وحكمته؛ فمن سلّم لله في قضائه رضي واطمأنّ، وأحسن الظنَّ بربه؛ فاجعل تسليمك لله في الولدِ وفي كلِّ قضاء؛ فهو العليمُ القديرُ الذي يدبّر أمرك بحكمته."}},{"n":51,"reflection":{"text":"«وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا فيوحي بإذنه ما يشاء إنه علي حكيم»، وما كان لبشرٍ أن يكلّمه الله إلا وحيًا (إلهامًا أو مناما)، أو من وراءِ حجابٍ (كموسى)، أو يرسل ملَكًا فيوحي بإذنه ما يشاء، إنه عليٌّ حكيم؛ ففي هذا بيانُ كيفيةِ كلامِ الله لعباده؛ فاعلم أنّ الله يكلّم من يشاء بالوحيِ بهذه الطرق، فعظّم كلامَ الله ووحيه، فمن كلّمه الله أو أوحى إليه بلغ أعلى المراتب، فعظّم الوحيَ الذي جاءك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ كلامِ الله ووحيه، وإدراكُ كيفيةِ تكليمِه لعباده."},"action":{"text":"تأمّل بيانَ كيفيةِ كلامِ الله لخلقه: وما كان لبشرٍ من الأنبياءِ أن يكلّمه الله مشافهةً معاينةً في الدنيا؛ بل يكلّمه بإحدى ثلاثِ طرق: إما وحيًا، إلهامًا في القلبِ أو رؤيا في المنام؛ أو من وراءِ حجابٍ، يسمع كلامه ولا يراه، كما كلّم موسى؛ أو يرسل رسولًا مَلَكًا، كجبريل، فيوحي بإذنِ الله ما يشاء؛ إنه عليٌّ في ذاته وصفاته، حكيمٌ في أفعاله وتدبيره «وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا فيوحي بإذنه ما يشاء إنه علي حكيم»؛ ففي هذا بيانُ كيفيةِ كلامِ الله لعباده وأنبيائه بالوحي؛ فالله يكلّم من يشاء من أنبيائه بهذه الطرقِ الثلاث؛ فاعلم عظمةَ كلامِ الله ووحيه؛ فعظّم كلامَ الله ووحيه الذي جاءك في القرآن؛ فمن كلّمه الله أو أوحى إليه بلغ أعلى المراتب؛ فالقرآنُ كلامُ الله أوحاه إلى نبيّه؛ فعظّمه، وأقبل عليه، واعمل به؛ فهو من العليِّ الحكيم؛ فمن عرف عظمةَ كلامِ الله عظّم القرآنَ وأقبل عليه؛ فاجعل للقرآنِ، كلامِ الله، في قلبك أعظمَ المكانة؛ فبتعظيمِ كلامِ الله يُنتفَع به ويُهتَدى بهديه."}},{"n":52,"reflection":{"text":"«وكذلك أوحينا إليك روحا من أمرنا ما كنت تدري ما الكتاب ولا الإيمان ولكن جعلناه نورا نهدي به من نشاء من عبادنا وإنك لتهدي إلى صراط مستقيم»، وكذلك أوحينا إليك قرآنًا من أمرنا، ما كنت تدري ما الكتابُ ولا تفاصيلُ الإيمان، ولكن جعلنا القرآنَ نورًا نهدي به من نشاء من عبادنا، وإنك لتهدي إلى صراطٍ مستقيم؛ ففي هذا بيانُ فضلِ القرآنِ الهادي وهدايةِ النبيّ؛ فاهتدِ بنورِ القرآنِ إلى الصراطِ المستقيم، فالقرآنُ نورٌ يهدي، فاجعله نورك وهاديك إلى الصراطِ المستقيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاهتداءُ بنورِ القرآنِ إلى الصراطِ المستقيم."},"action":{"text":"تأمّل فضلَ القرآنِ الهادي: وكذلك، كما أوحينا إلى من قبلك، أوحينا إليك يا محمدُ روحًا، وهو القرآنُ الذي تحيا به القلوبُ، من أمرنا؛ ما كنت تدري قبل الوحيِ ما الكتابُ ولا تفاصيلُ الإيمانِ وشرائعه؛ ولكن جعلنا هذا القرآنَ نورًا نهدي به من نشاء من عبادنا؛ وإنك يا محمدُ لتهدي الناسَ وتدلّهم إلى صراطٍ مستقيم «وكذلك أوحينا إليك روحا من أمرنا ما كنت تدري ما الكتاب ولا الإيمان ولكن جعلناه نورا نهدي به من نشاء من عبادنا وإنك لتهدي إلى صراط مستقيم»؛ ففي هذا بيانُ فضلِ القرآنِ الهادي، وأنه روحٌ ونورٌ، وأنّ النبيَّ يهدي به إلى الصراطِ المستقيم؛ فالقرآنُ روحٌ تحيا به القلوبُ الميتة، ونورٌ يُهتَدى به في ظلماتِ الجهلِ والضلال؛ فاهتدِ بنورِ القرآنِ إلى الصراطِ المستقيم؛ فالقرآنُ نورٌ يهدي؛ أفمن كان ميتًا فأحييناه وجعلنا له نورًا يمشي به في الناس؛ فاجعل القرآنَ نورك وهاديك في حياتك؛ فبه تحيا قلوبك، وتهتدي إلى الصراطِ المستقيم؛ فمن اهتدى بنورِ القرآنِ سلك الصراطَ المستقيم؛ ومن أعرض عنه بقي في ظلماتِ الجهلِ والضلال؛ فاستضئ بنورِ القرآن؛ واهتدِ بهديه إلى صراطِ الله المستقيم."}},{"n":53,"reflection":{"text":"«صراط الله الذي له ما في السماوات وما في الأرض ألا إلى الله تصير الأمور»: صراطِ الله الذي له ملكُ ما في السماواتِ والأرض، ألا إلى الله تصير الأمورُ كلُّها؛ ففي هذا تقريرُ أنّ الصراطَ المستقيمَ صراطُ الله، وأنّ المرجعَ إليه؛ فاسلك صراطَ الله المستقيم، واعلم أنّ مرجعك ومرجعَ الأمورِ كلِّها إلى الله، فاستعدّ للقائه، فإلى الله تصير الأمور.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"سلوكُ صراطِ الله المستقيم، والاستعدادُ لمصيرِ الأمورِ إليه."},"action":{"text":"تأمّل ختامَ السورةِ العظيم: هو صراطُ الله المستقيمُ الذي له وحده ملكُ ما في السماواتِ وما في الأرض؛ ألا إلى الله وحده تصير وترجع الأمورُ كلُّها فيفصل فيها ويجازي عليها «صراط الله الذي له ما في السماوات وما في الأرض ألا إلى الله تصير الأمور»؛ ففي هذا تقريرُ أنّ الصراطَ المستقيمَ هو صراطُ الله المالكِ لكلِّ شيء، وأنّ مرجعَ الأمورِ كلِّها إليه؛ فاسلك صراطَ الله المستقيمَ الذي يهدي إليه القرآن؛ فهو صراطُ الله المالكِ للسماواتِ والأرض؛ اهدنا الصراطَ المستقيم؛ فالزم الصراطَ المستقيم؛ ولا تحد عنه يمينًا ولا شمالًا؛ واعلم أنّ مرجعك ومرجعَ الأمورِ كلِّها إلى الله؛ فإلى الله تصير الأمور؛ فاستعدّ للقائه ولمصيرِ الأمورِ إليه بالإيمانِ والعملِ الصالح؛ فمن سلك صراطَ الله المستقيمَ واستعدّ للقائه فاز؛ ومن حاد عنه وغفل عن مصيرِ الأمورِ إلى الله خسر؛ فاجعل همّك سلوكَ صراطِ الله المستقيم، والاستعدادَ لمصيرِ الأمورِ إليه؛ فبهذا تُختَم السورةُ التي بدأت بوحدةِ الوحي، لتحمل القلبَ على سلوكِ صراطِ الله والاستعدادِ للقائه؛ فإلى الله تصير الأمورُ كلُّها؛ فاعمل لذلك المصير."}}]}],"coverage":{"covered":53,"total":53}};
